CREATE OR REPLACE FUNCTION public.generate_unique_handle(_seed text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  base text;
  candidate text;
  i int := 0;
begin
  base := regexp_replace(lower(coalesce(_seed, 'member')), '[^a-z0-9]+', '', 'g');
  if length(base) < 3 then base := base || 'member'; end if;
  base := left(base, 20);
  candidate := base;
  while not public.is_handle_available(candidate) loop
    i := i + 1;
    candidate := left(base, 20) || i::text;
    exit when i > 9999;
  end loop;
  return candidate;
end;
$function$

CREATE OR REPLACE FUNCTION public.identity_event_chain()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare owner_id uuid;
begin
  if TG_OP <> 'INSERT' then raise exception 'identity_events_append_only'; end if;
  -- Serialize the chain on the identity row, including the first event.
  select user_id into owner_id from public.identity_links where id = NEW.link_id for update;
  if owner_id is null or owner_id <> NEW.user_id then raise exception 'identity_event_owner_mismatch'; end if;
  select event_hash into NEW.prev_hash from public.identity_link_events where link_id = NEW.link_id order by id desc limit 1;
  NEW.event_hash := public.digest(coalesce(NEW.prev_hash, ''::bytea) || convert_to(
    jsonb_build_object('link_id',NEW.link_id,'user_id',NEW.user_id,'event',NEW.event,'actor',NEW.actor,
      'ip_hash',encode(NEW.ip_hash,'hex'),'ua_hash',encode(NEW.ua_hash,'hex'),
      'created_at',to_char(NEW.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::text,'UTF8'),'sha256');
  return NEW;
end $function$

CREATE OR REPLACE FUNCTION public.identity_owner_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if NEW.user_id <> OLD.user_id or NEW.issuer <> OLD.issuer or NEW.provider_sub <> OLD.provider_sub then
    raise exception 'identity_owner_immutable';
  end if;
  return NEW;
end $function$

CREATE OR REPLACE FUNCTION public.log_qr_scan(_tracked_qr_id uuid, _device text DEFAULT NULL::text, _country text DEFAULT NULL::text, _browser text DEFAULT NULL::text, _os text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare recent int;
begin
  if _tracked_qr_id is null then return; end if;

  select count(*) into recent
    from public.qr_scans
   where tracked_qr_id = _tracked_qr_id
     and scanned_at > now() - interval '1 minute';

  if recent >= 60 then return; end if;

  insert into public.qr_scans (tracked_qr_id, device, country, browser, os)
  values (_tracked_qr_id, left(_device, 20), left(_country, 2), left(_browser, 20), left(_os, 20));
end;
$function$

CREATE OR REPLACE FUNCTION public.manage_short_link(_token text, _action text, _target_url text DEFAULT NULL::text, _is_active boolean DEFAULT NULL::boolean, _expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _slug text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  row public.tracked_qrs;
begin
  select * into row from public.tracked_qrs where dashboard_token = _token limit 1;
  if row.id is null then
    raise exception 'Dashboard not found';
  end if;

  if _action = 'update_target' then
    if _target_url is null or length(_target_url) < 3 then
      raise exception 'Invalid target url';
    end if;
    update public.tracked_qrs set target_url = _target_url, updated_at = now() where id = row.id;
  elsif _action = 'set_active' then
    update public.tracked_qrs set is_active = coalesce(_is_active, true), updated_at = now() where id = row.id;
  elsif _action = 'set_expiry' then
    update public.tracked_qrs set expires_at = _expires_at, updated_at = now() where id = row.id;
  elsif _action = 'regenerate_slug' then
    if _slug is null then raise exception 'Missing slug'; end if;
    update public.tracked_qrs set slug = lower(_slug), updated_at = now() where id = row.id;
  elsif _action = 'delete' then
    delete from public.tracked_qrs where id = row.id;
  else
    raise exception 'Unknown action %', _action;
  end if;

  return jsonb_build_object('ok', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.patch_profile_draft(p_user_id uuid, p_space text, p_fields jsonb, p_prefs jsonb, p_drop_prefs text[])
 RETURNS TABLE(revision bigint, published_revision bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_fields jsonb := coalesce(p_fields, '{}'::jsonb);
  v_prefs jsonb := coalesce(p_prefs, '{}'::jsonb);
begin
  if p_space not in ('verified', 'alias') then
    raise exception 'draft_space_invalid';
  end if;
  if jsonb_typeof(v_fields) <> 'object' or jsonb_typeof(v_prefs) <> 'object' then
    raise exception 'validation: draft patch must be an object';
  end if;

  return query
    update public.profile_drafts d
       set payload = (
             (case when jsonb_typeof(d.payload) = 'object' then d.payload else '{}'::jsonb end)
             || (v_fields - 'displayPrefs')
           ) || jsonb_build_object(
             'displayPrefs',
             ((case when jsonb_typeof(d.payload -> 'displayPrefs') = 'object'
                    then d.payload -> 'displayPrefs' else '{}'::jsonb end)
               - coalesce(p_drop_prefs, '{}'::text[]))
             || v_prefs
           ),
           revision = d.revision + 1,
           updated_at = now()
     where d.user_id = p_user_id and d.space = p_space
    returning d.revision, d.published_revision;

  if not found then
    raise exception 'draft_not_found';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.profiles_handle_namespace_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.username is distinct from coalesce(old.username, null) then
    perform public.assert_handle_namespace_free(new.username, new.id);
  end if;
  if new.subdomain_alias is distinct from coalesce(old.subdomain_alias, null) then
    perform public.assert_handle_namespace_free(new.subdomain_alias, new.id);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.queue_presence_broadcast()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare owner uuid; event uuid; canvas text; message text;
begin
 if tg_table_name='profile_questions' then
  if not new.published or new.answer is null or new.is_quarantined then return new;end if;
  owner:=new.owner_id;event:=new.id;canvas:=new.space;message:=new.body||E'\n\n'||new.answer;
 else
  owner:=new.user_id;event:=new.id;canvas:=new.space;
  if new.status_type<>'micro_text' then return new;end if;
  message:=new.content_payload->>'text';
 end if;
 if not public.rout_broadcast_event_allowed(owner,event,canvas) then return new;end if;
 insert into public.presence_broadcast_jobs(user_id,event_id,space,provider,payload)
 select owner,event,canvas,provider,jsonb_build_object('text',left(message,4000)) from public.user_integrations
 where user_id=owner and provider in ('omnicast_mastodon','omnicast_bluesky','omnicast_telegram','omnicast_webhook')
 and connection_status='connected' and coalesce(status_json->'broadcastSpaces','[]'::jsonb) ? canvas
 on conflict(user_id,event_id,provider) do nothing;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.reserve_recovery_email()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if exists (select 1 from public.account_email_changes c where lower(c.old_email)=lower(new.email)
      and c.user_id<>new.id and c.recovery_until>now()) then
    raise exception 'email_reserved_for_recovery';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.rotate_oauth_refresh(old_hash text, target_client text, new_hash text)
 RETURNS TABLE(result text, user_id uuid, subject text, scopes text[], family_id uuid, auth_time timestamp with time zone, acr text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare old public.oauth_refresh_tokens%rowtype;
begin
  select * into old from public.oauth_refresh_tokens t where t.token_hash=old_hash and t.client_id=target_client for update;
  if not found then return query select 'invalid'::text,null::uuid,null::text,null::text[],null::uuid,null::timestamptz,null::text; return; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(old.family_id::text,0));
  if old.used_at is not null then
    update public.oauth_refresh_tokens t set revoked_at=coalesce(t.revoked_at,now()) where t.family_id=old.family_id;
    update public.oauth_access_tokens t set revoked_at=coalesce(t.revoked_at,now()) where t.family_id=old.family_id;
    return query select 'reuse'::text,null::uuid,null::text,null::text[],old.family_id,null::timestamptz,null::text; return;
  end if;
  if old.revoked_at is not null or old.expires_at<=now()
    or exists(select 1 from public.oauth_refresh_tokens t where t.family_id=old.family_id and t.revoked_at is not null)
    or not exists(select 1 from public.oauth_consents c where c.user_id=old.user_id and c.client_id=target_client and c.revoked_at is null and 'offline_access'=any(c.scopes))
    or not exists(select 1 from public.users u where u.id=old.user_id and not u.is_disabled and u.account_status='active')
    or not exists(select 1 from public.oauth_clients c where c.client_id=target_client and c.status='active') then
    return query select 'invalid'::text,null::uuid,null::text,null::text[],old.family_id,null::timestamptz,null::text; return;
  end if;
  update public.oauth_refresh_tokens t set used_at=now() where t.id=old.id;
  insert into public.oauth_refresh_tokens(family_id,token_hash,client_id,user_id,scopes,expires_at,subject,auth_time,acr)
  values(old.family_id,new_hash,target_client,old.user_id,old.scopes,old.expires_at,old.subject,old.auth_time,old.acr);
  return query select 'ok'::text,old.user_id,old.subject,old.scopes,old.family_id,old.auth_time,old.acr;
end $function$

CREATE OR REPLACE FUNCTION public.rout_admin_bootstrap_claim(p_token_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_user uuid := public.rout_current_user_id();
begin
  if v_user is null or p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then return false; end if;
  perform pg_advisory_xact_lock(hashtextextended('rout.admin_bootstrap', 0));
  if public.rout_any_admin() then return false; end if;
  if (select u.id from public.users u order by u.created_at asc limit 1) is distinct from v_user then return false; end if;
  insert into public.admin_bootstrap_tokens (token_hash, consumed_by, consumed_at)
  values (p_token_hash, v_user, now()) on conflict (token_hash) do nothing;
  if not found then return false; end if;
  insert into public.user_roles (user_id, role) values (v_user, 'admin') on conflict (user_id, role) do nothing;
  perform public.rout_audit_insert(v_user, (select email from public.users where id = v_user),
    'ADMIN_BOOTSTRAP_CLAIMED', v_user, null, null);
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.rout_admin_grant_owner()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_user uuid := public.rout_current_user_id();
begin
  if v_user is null or not exists (
    select 1 from public.users u join public.admin_owner_emails o on o.email = lower(u.email)
     where u.id = v_user) then
    return false;
  end if;
  insert into public.user_roles (user_id, role) values (v_user, 'admin') on conflict (user_id, role) do nothing;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.rout_admin_permission_set(p_target uuid, p_permission text, p_granted boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_actor uuid := public.rout_current_user_id();
begin
  if not public.rout_caller_has_admin_permission('manage_admins') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_target is null or p_permission is null or p_permission not in ('verify_users', 'edit_names',
       'manage_promos', 'view_device_data', 'block_features', 'manage_admins', 'approve_sepa',
       'grant_badges', 'manage_integrations', 'review_apps', 'export_data', 'triage_contact') then
    return false;
  end if;
  if p_granted then
    insert into public.admin_permissions (user_id, permission, granted_by)
    values (p_target, p_permission, v_actor) on conflict (user_id, permission) do nothing;
  else
    delete from public.admin_permissions where user_id = p_target and permission = p_permission;
  end if;
  perform public.rout_audit_insert(v_actor, (select email from public.users where id = v_actor),
    case when p_granted then 'admin_permission_grant' else 'admin_permission_revoke' end,
    p_target, p_permission, null);
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.rout_agent_provision_workspace(p_client_id text, p_name text, p_slug text, p_description text, p_token_hash text)
 RETURNS TABLE(workspace_id uuid, slug text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_uid uuid := public.rout_current_user_id();
  v_open integer;
  v_ws uuid;
  v_now timestamptz := now();
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  perform pg_advisory_xact_lock(hashtext('agent_provision:' || v_uid::text));
  select count(*) into v_open from public.agent_workspace_claims c
   where c.requested_by = v_uid and c.claimed_at is null and c.expires_at > v_now;
  if v_open >= 3 then raise exception 'agent_quota_reached'; end if;
  if exists (select 1 from public.workspaces w where w.slug = lower(p_slug)) then
    raise exception 'slug_taken';
  end if;
  insert into public.workspaces (name, slug, description, plan)
  values (p_name, lower(p_slug), nullif(p_description, ''), 'free')
  returning id into v_ws;
  insert into public.agent_workspace_claims (workspace_id, client_id, requested_by, token_hash, created_at, expires_at)
  values (v_ws, p_client_id, v_uid, p_token_hash, v_now, v_now + interval '24 hours');
  return query select v_ws, lower(p_slug), v_now + interval '24 hours';
end;
$function$

CREATE OR REPLACE FUNCTION public.rout_agent_sandbox_provision(p_key_hash text, p_name text, p_slug text, p_description text, p_token_hash text, p_code_hash text, p_draft jsonb)
 RETURNS TABLE(workspace_id uuid, slug text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_s public.agent_sandboxes%rowtype; v_ws uuid; v_slug text;
begin
  select * into v_s from public.agent_sandboxes s
   where s.key_hash = p_key_hash and s.revoked_at is null and s.expires_at > now() for update;
  if not found then raise exception 'sandbox_invalid'; end if;
  if v_s.workspace_id is not null then raise exception 'sandbox_has_workspace'; end if;
  if exists (select 1 from public.workspaces w where w.slug = lower(p_slug)) then raise exception 'slug_taken'; end if;
  if jsonb_typeof(p_draft) <> 'object' then raise exception 'validation: draft must be an object'; end if;

  insert into public.workspaces (name, slug, description, plan)
  values (p_name, lower(p_slug), nullif(p_description, ''), 'free') returning id, workspaces.slug into v_ws, v_slug;
  insert into public.agent_workspace_claims (workspace_id, client_id, requested_by, token_hash, code_hash, sandbox_id, created_at, expires_at)
  values (v_ws, 'sandbox:' || v_s.id::text, null, p_token_hash, p_code_hash, v_s.id, v_s.created_at, v_s.expires_at);
  insert into public.workspace_profile_drafts (workspace_id, payload)
  values (v_ws, jsonb_set(p_draft, '{username}', to_jsonb(v_slug), true));
  update public.agent_sandboxes s set workspace_id = v_ws where s.id = v_s.id;
  return query select v_ws, v_slug, v_s.expires_at;
end; $function$

CREATE OR REPLACE FUNCTION public.rout_agent_sandbox_register(p_key_hash text, p_pow_hash text, p_ip_bucket text, p_agent_name text)
 RETURNS TABLE(sandbox_id uuid, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_now timestamptz := now(); v_id uuid; v_count integer;
begin
  perform pg_advisory_xact_lock(hashtext('agent_sandbox_ip:' || p_ip_bucket));
  select count(*) into v_count from public.agent_sandboxes s
   where s.ip_bucket = p_ip_bucket and s.created_at > v_now - interval '24 hours';
  if v_count >= 5 then raise exception 'sandbox_quota_reached'; end if;
  if exists (select 1 from public.agent_sandboxes s where s.pow_hash = p_pow_hash) then
    raise exception 'challenge_used';
  end if;
  insert into public.agent_sandboxes (key_hash, pow_hash, ip_bucket, agent_name, created_at, expires_at)
  values (p_key_hash, p_pow_hash, p_ip_bucket, p_agent_name, v_now, v_now + interval '24 hours')
  returning id into v_id;
  return query select v_id, v_now + interval '24 hours';
end; $function$

CREATE OR REPLACE FUNCTION public.rout_agent_sandbox_set_apps(p_key_hash text, p_apps jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_ws uuid;
begin
  if jsonb_typeof(p_apps) <> 'array' or jsonb_array_length(p_apps) > 3 then raise exception 'validation: max 3 apps'; end if;
  select s.workspace_id into v_ws from public.agent_sandboxes s
   where s.key_hash = p_key_hash and s.revoked_at is null and s.expires_at > now();
  if v_ws is null then raise exception 'sandbox_invalid'; end if;
  update public.agent_workspace_claims c set pending_apps = p_apps
   where c.workspace_id = v_ws and c.claimed_at is null;
  if not found then raise exception 'sandbox_claimed'; end if;
  return jsonb_array_length(p_apps);
end; $function$

CREATE OR REPLACE FUNCTION public.rout_alias_job_enqueue(p_user uuid, p_action text, p_payload jsonb, p_max_attempts integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_id uuid;
begin
  if p_user is null or p_action not in ('provision', 'rename', 'pause', 'resume', 'delete', 'freeze')
     or pg_catalog.octet_length(coalesce(p_payload, '{}'::jsonb)::text) > 4096
     or p_max_attempts is null or p_max_attempts not between 1 and 10 then
    raise exception 'invalid alias job' using errcode = '22023';
  end if;
  insert into public.alias_sync_jobs (user_id, action, payload, max_attempts)
  values (p_user, p_action, coalesce(p_payload, '{}'::jsonb), p_max_attempts)
  returning id into v_id;
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.rout_alias_jobs_retry_failed()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare n int;
begin
  update public.alias_sync_jobs j set status = 'pending', attempts = 0, last_error = null, updated_at = pg_catalog.now()
   where j.status = 'failed';
  get diagnostics n = row_count;
  return n;
end $function$

CREATE OR REPLACE FUNCTION public.rout_altcha_purge()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare n int;
begin
  delete from public.altcha_used where expires_at < pg_catalog.now();
  get diagnostics n = row_count;
  return n;
end $function$

CREATE OR REPLACE FUNCTION public.rout_altcha_verify_and_burn(p_signature text, p_expires_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v text;
begin
  if p_signature is null or p_signature !~ '^[0-9a-f]{64}$' or p_expires_at is null then return 'invalid'; end if;
  if p_expires_at <= pg_catalog.now() then return 'expired'; end if;
  if p_expires_at > pg_catalog.now() + interval '1 day' then return 'invalid'; end if;
  insert into public.altcha_used (signature, expires_at) values (p_signature, p_expires_at)
  on conflict (signature) do nothing
  returning signature into v;
  return case when v is null then 'replayed' else 'ok' end;
end $function$

CREATE OR REPLACE FUNCTION public.rout_audit_actions()
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
begin
  if not public.rout_is_admin_member(public.rout_current_user_id()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  return (select coalesce(array_agg(distinct a.action order by a.action), '{}'::text[])
            from (select action from public.admin_audit_log order by created_at desc limit 1000) a);
end $function$

CREATE OR REPLACE FUNCTION public.rout_audit_purge_expired()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare n int;
begin
  perform pg_catalog.set_config('rout.audit_retention', 'on', true);
  delete from public.security_audit_logs where created_at < pg_catalog.now() - interval '365 days';
  get diagnostics n = row_count;
  perform pg_catalog.set_config('rout.audit_retention', '', true);
  return n;
end $function$

CREATE OR REPLACE FUNCTION public.rout_audit_write(p_action text, p_target uuid, p_label text, p_notes text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_actor uuid := public.rout_current_user_id(); v_email text;
begin
  if v_actor is null or not public.rout_is_admin_member(v_actor)
     or p_action is null or p_action !~ '^[A-Za-z0-9_.:-]{1,80}$' then
    return false;
  end if;
  select u.email into v_email from public.users u where u.id = v_actor;
  perform public.rout_audit_insert(v_actor, v_email, p_action, p_target, p_label, p_notes);
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.rout_auth_secrets_clear()
