CREATE OR REPLACE FUNCTION public.rout_booking_cache_free(p_host uuid, p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  first_slot bigint := floor(extract(epoch from p_from) / 900);
  last_slot bigint := ceil(extract(epoch from p_to) / 900);
  s bigint; day_start bigint; bits text; cur date; want date;
begin
  if p_to <= p_from then return false; end if;
  cur := null;
  for s in first_slot .. last_slot - 1 loop
    want := (to_timestamp(s * 900) at time zone 'utc')::date;
    if cur is distinct from want then
      select c.free_bits::text into bits from public.availability_cache c where c.user_id = p_host and c.day = want;
      if bits is null then return false; end if;
      cur := want;
      day_start := floor(extract(epoch from (want::timestamp at time zone 'utc')) / 900);
    end if;
    if substr(bits, (s - day_start + 1)::int, 1) <> '1' then return false; end if;
  end loop;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.rout_booking_create(p_event_type uuid, p_start timestamp with time zone, p_guest_name text, p_guest_email text, p_guest_timezone text, p_guest_note text, p_intake jsonb, p_hold uuid, p_hold_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  t public.booking_event_types%rowtype; problem text; chosen uuid[]; held uuid[];
  bs timestamptz; be timestamptz; e timestamptz; cap integer; shared boolean; st text; hold timestamptz;
  grp uuid; ids uuid[] := '{}'; tok text; h uuid; i integer; new_id uuid; own uuid;
begin
  if not public.rout_booking_type_public(p_event_type) then return jsonb_build_object('ok', false, 'reason', 'inactive'); end if;
  select * into t from public.booking_event_types where id = p_event_type;
  if p_guest_name is null or char_length(btrim(p_guest_name)) not between 1 and 120
     or p_guest_email is null or char_length(p_guest_email) not between 3 and 254 or position('@' in p_guest_email) < 2
     or p_guest_timezone is null or char_length(p_guest_timezone) not between 1 and 64
     or char_length(coalesce(p_guest_note, '')) > 2000
     or (p_intake is not null and (jsonb_typeof(p_intake) <> 'object' or octet_length(p_intake::text) > 65536)) then
    return jsonb_build_object('ok', false, 'reason', 'invalid_input');
  end if;
  problem := public.rout_booking_start_problem(t.id, p_start);
  if problem is not null then return jsonb_build_object('ok', false, 'reason', problem); end if;

  e := p_start + make_interval(mins => t.duration_minutes);
  bs := p_start - make_interval(mins => t.buffer_before_minutes);
  be := e + make_interval(mins => t.buffer_after_minutes);
  cap := greatest(1, t.resource_capacity);
  shared := cap > 1;
  st := case when t.price_cents is not null then 'pending_payment' when t.confirmation_mode = 'request' then 'requested' else 'confirmed' end;
  hold := case when t.price_cents is not null then now() + interval '30 minutes' end;

  perform public.rout_booking_lock_type(t.id, p_start);

  -- Per-guest cap on active future bookings of this type (a collective group counts once).
  if t.limit_per_guest is not null and (
      select count(distinct coalesce(b.group_id, b.id)) from public.bookings b
      where b.event_type_id = t.id and lower(b.guest_email) = lower(p_guest_email) and b.end_utc > now()
        and b.status in ('held','pending_payment','requested','confirmed')) >= t.limit_per_guest then
    return jsonb_build_object('ok', false, 'reason', 'guest_limit');
  end if;

  if p_hold is not null and p_hold_secret ~ '^[a-f0-9]{64}$' then
    select array_agg(x.host_user_id order by x.host_user_id) into held from public.booking_holds x
    where x.hold_id = p_hold and x.event_type_id = t.id and x.start_utc = p_start and x.expires_at > now()
      and x.secret_digest = sha256(convert_to(p_hold_secret, 'UTF8'));
  end if;
  if held is not null then
    own := p_hold;
    foreach h in array held loop
      if not public.rout_booking_host_free_held(h, t.id, p_start, bs, be, cap, own) then
        return jsonb_build_object('ok', false, 'reason', 'slot_taken');
      end if;
    end loop;
    chosen := held;
  else
    chosen := public.rout_booking_pick_hosts(t.id, p_start, null);
    if chosen is null then return jsonb_build_object('ok', false, 'reason', 'slot_taken'); end if;
  end if;

  if own is not null then delete from public.booking_holds where hold_id = own; end if;
  grp := case when array_length(chosen, 1) > 1 then gen_random_uuid() end;
  begin
    for i in 1 .. array_length(chosen, 1) loop
      new_id := gen_random_uuid();
      insert into public.bookings (id, event_type_id, host_user_id, workspace_id, group_id, start_utc, end_utc,
        block_start_utc, block_end_utc, status, guest_name, guest_email, guest_timezone, guest_note, hold_expires_at,
        ics_uid, shared_slot, intake_answers)
      values (new_id, t.id, chosen[i], t.workspace_id, grp, p_start, e, bs, be, st, btrim(p_guest_name), p_guest_email,
        p_guest_timezone, nullif(p_guest_note, ''), hold, coalesce(grp, new_id)::text || '@rout.be', shared, p_intake);
      ids := ids || new_id;
      insert into public.availability_jobs (user_id, reason, run_after) values (chosen[i], 'booking', now() + interval '20 seconds')
        on conflict (user_id) do update set reason = 'booking', run_after = least(public.availability_jobs.run_after, excluded.run_after);
    end loop;
  exception when exclusion_violation then
    return jsonb_build_object('ok', false, 'reason', 'slot_taken');
  end;
  select booking_token into tok from public.bookings where id = ids[1];
  return jsonb_build_object('ok', true, 'bookingIds', to_jsonb(ids), 'hostIds', to_jsonb(chosen), 'token', tok,
    'status', st, 'holdExpiresAt', hold, 'groupId', grp);
end $function$

CREATE OR REPLACE FUNCTION public.rout_booking_hold(p_event_type uuid, p_start timestamp with time zone, p_client text, p_replace uuid, p_replace_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  t public.booking_event_types%rowtype; problem text; chosen uuid[]; h uuid;
  secret text := encode(public.gen_random_bytes(32), 'hex'); hid uuid := gen_random_uuid();
  exp timestamptz := now() + interval '5 minutes'; client bytea; bs timestamptz; be timestamptz;
begin
  if not public.rout_booking_type_public(p_event_type) then return jsonb_build_object('ok', false, 'reason', 'inactive'); end if;
  if p_client is null or p_client !~ '^[a-f0-9]{64}$' then return jsonb_build_object('ok', false, 'reason', 'invalid_input'); end if;
  client := decode(p_client, 'hex');
  select * into t from public.booking_event_types where id = p_event_type;
  if p_replace is not null and p_replace_secret ~ '^[a-f0-9]{64}$' then
    delete from public.booking_holds where hold_id = p_replace and secret_digest = sha256(convert_to(p_replace_secret, 'UTF8'));
  end if;
  problem := public.rout_booking_start_problem(t.id, p_start);
  if problem is not null then return jsonb_build_object('ok', false, 'reason', problem); end if;
  if (select count(distinct hold_id) from public.booking_holds where client_digest = client and expires_at > now()) >= 3 then
    return jsonb_build_object('ok', false, 'reason', 'too_many_holds');
  end if;
  perform public.rout_booking_lock_type(t.id, p_start);
  chosen := public.rout_booking_pick_hosts(t.id, p_start, null);
  if chosen is null then return jsonb_build_object('ok', false, 'reason', 'slot_taken'); end if;
  bs := p_start - make_interval(mins => t.buffer_before_minutes);
  be := p_start + make_interval(mins => t.duration_minutes + t.buffer_after_minutes);
  begin
    foreach h in array chosen loop
      insert into public.booking_holds (hold_id, host_user_id, event_type_id, start_utc, block_start_utc, block_end_utc,
        shared_slot, secret_digest, client_digest, expires_at)
      values (hid, h, t.id, p_start, bs, be, greatest(1, t.resource_capacity) > 1,
        sha256(convert_to(secret, 'UTF8')), client, exp);
    end loop;
  exception when exclusion_violation then
    return jsonb_build_object('ok', false, 'reason', 'slot_taken');
  end;
  return jsonb_build_object('ok', true, 'holdId', hid, 'secret', secret, 'expiresAt', exp, 'startUtc', p_start);
end $function$

CREATE OR REPLACE FUNCTION public.rout_booking_horizon_end(p_business_days integer, p_max_days integer, p_zone text, p_now timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare d date; n integer := 0; cap timestamptz := p_now + make_interval(days => p_max_days);
begin
  if p_business_days is null then return cap; end if;
  d := (p_now at time zone p_zone)::date;
  loop
    if extract(isodow from d) < 6 then n := n + 1; end if;
    exit when n >= p_business_days;
    d := d + 1;
  end loop;
  return least(cap, ((d + 1)::timestamp) at time zone p_zone);
end $function$

CREATE OR REPLACE FUNCTION public.rout_booking_lock_hosts(p_hosts uuid[], p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare h uuid; d date;
begin
  for h in select x from unnest(p_hosts) x group by x order by x loop
    d := (p_from at time zone 'utc')::date;
    while d <= ((p_to - interval '1 microsecond') at time zone 'utc')::date loop
      perform pg_advisory_xact_lock(hashtextextended('booking:' || h::text || ':' || d::text, 0));
      d := d + 1;
    end loop;
  end loop;
end $function$

CREATE OR REPLACE FUNCTION public.rout_booking_lock_type(p_event_type uuid, p_start timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare t public.booking_event_types%rowtype; hosts uuid[]; bs timestamptz; be timestamptz;
begin
  select * into t from public.booking_event_types where id = p_event_type;
  select array_agg(user_id order by user_id) into hosts from public.booking_event_type_hosts where event_type_id = t.id;
  bs := p_start - make_interval(mins => t.buffer_before_minutes);
  be := p_start + make_interval(mins => t.duration_minutes + t.buffer_after_minutes);
  perform public.rout_booking_lock_hosts(hosts, bs, be);
  delete from public.booking_holds x where x.host_user_id = any(hosts) and x.expires_at <= now();
end $function$

CREATE OR REPLACE FUNCTION public.rout_booking_pick_hosts(p_event_type uuid, p_start timestamp with time zone, p_hold uuid)
 RETURNS uuid[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  t public.booking_event_types%rowtype; bs timestamptz; be timestamptz; cap integer;
  hosts uuid[]; candidates uuid[]; h uuid;
begin
  select * into t from public.booking_event_types where id = p_event_type;
  bs := p_start - make_interval(mins => t.buffer_before_minutes);
  be := p_start + make_interval(mins => t.duration_minutes + t.buffer_after_minutes);
  cap := greatest(1, t.resource_capacity);
  if t.routing_strategy = 'COLLECTIVE' then
    select array_agg(user_id order by user_id) into hosts from public.booking_event_type_hosts where event_type_id = t.id;
    foreach h in array hosts loop
      if not (public.rout_booking_host_free_held(h, t.id, p_start, bs, be, cap, p_hold)
          and public.rout_booking_within_limits(t.id, h, p_start, p_hold)
          and (not t.adjacent_only or public.rout_booking_adjacent_ok(h, bs, be))) then
        return null;
      end if;
    end loop;
    return hosts;
  end if;
  select array_agg(x.user_id order by x.load, x.priority desc, x.user_id) into candidates from (
    select h2.user_id, h2.priority,
      case when t.routing_strategy = 'ROUND_ROBIN' then coalesce((
        select sum(extract(epoch from (b.end_utc - b.start_utc)) / 60) from public.bookings b
        where b.host_user_id = h2.user_id and b.status in ('held','pending_payment','requested','confirmed')
          and b.start_utc >= p_start - interval '30 days' and b.start_utc < p_start + interval '30 days'), 0) else 0 end as load
    from public.booking_event_type_hosts h2 where h2.event_type_id = t.id) x;
  if t.routing_strategy = 'STRICT' then candidates := candidates[1:1]; end if;
  foreach h in array coalesce(candidates, '{}') loop
    if public.rout_booking_host_free_held(h, t.id, p_start, bs, be, cap, p_hold)
        and public.rout_booking_within_limits(t.id, h, p_start, p_hold)
        and (not t.adjacent_only or public.rout_booking_adjacent_ok(h, bs, be)) then
      return array[h];
    end if;
  end loop;
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.rout_booking_public_constraints(p_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_hold uuid)
 RETURNS TABLE(host_ordinal integer, kind text, start_utc timestamp with time zone, end_utc timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare t public.booking_event_types%rowtype; r record; unit text; lim integer; zone text;
begin
  if not public.rout_booking_type_public(p_id) then return; end if;
  select * into t from public.booking_event_types where id = p_id;
  if p_to > p_from + interval '400 days' then p_to := p_from + interval '400 days'; end if;
  for r in select h.user_id, row_number() over (order by h.user_id)::integer as ord
      from public.booking_event_type_hosts h where h.event_type_id = p_id loop
    return query select r.ord, 'busy'::text, x.block_start_utc, x.block_end_utc
      from public.booking_holds x where x.host_user_id = r.user_id and x.expires_at > now()
        and x.hold_id is distinct from p_hold and x.block_end_utc > p_from and x.block_start_utc < p_to
        and not (greatest(1, t.resource_capacity) > 1 and x.shared_slot and x.event_type_id = p_id);
    zone := public.rout_booking_zone(t.rules_timezone, r.user_id);
    foreach unit in array array['day', 'week', 'month'] loop
      lim := case unit when 'day' then t.limit_per_day when 'week' then t.limit_per_week else t.limit_per_month end;
      continue when lim is null;
      return query
        select r.ord, 'limit'::text, (q.p at time zone zone), ((q.p + ('1 ' || unit)::interval) at time zone zone)
        from (
          select date_trunc(unit, k.s at time zone zone) as p, count(distinct k.k) as n from (
            select b.start_utc as s, case when b.shared_slot then 'S' || b.start_utc::text else b.id::text end as k
            from public.bookings b where b.host_user_id = r.user_id and b.event_type_id = p_id
              and b.status in ('held','pending_payment','requested','confirmed')
              and b.start_utc >= p_from - interval '32 days' and b.start_utc < p_to + interval '32 days'
            union all
            select x.start_utc, case when x.shared_slot then 'S' || x.start_utc::text else 'H' || x.hold_id::text end
            from public.booking_holds x where x.host_user_id = r.user_id and x.event_type_id = p_id
              and x.expires_at > now() and x.hold_id is distinct from p_hold
              and x.start_utc >= p_from - interval '32 days' and x.start_utc < p_to + interval '32 days') k
          group by 1) q
        where q.n >= lim;
    end loop;
  end loop;
end $function$

CREATE OR REPLACE FUNCTION public.rout_booking_release_expired(p_limit integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare r record; n integer := 0; m integer;
begin
  for r in select id from public.bookings where status in ('held','pending_payment')
      and hold_expires_at < now() - interval '5 minutes' order by hold_expires_at limit least(greatest(p_limit, 1), 500) loop
    n := n + public.rout_booking_release_hold(r.id);
  end loop;
  delete from public.booking_holds where expires_at < now() - interval '1 minute';
  get diagnostics m = row_count;
  return n + m;
end $function$

CREATE OR REPLACE FUNCTION public.rout_booking_start_problem(p_event_type uuid, p_start timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare t public.booking_event_types%rowtype;
begin
  select * into t from public.booking_event_types where id = p_event_type;
  if p_start is null or extract(epoch from p_start) % (t.slot_step_minutes * 60) <> 0 then return 'outside_availability'; end if;
  if p_start < now() + make_interval(hours => t.minimum_notice_hours) then return 'too_soon'; end if;
  if p_start >= public.rout_booking_horizon_end(t.horizon_business_days, t.max_days_ahead,
      public.rout_booking_type_zone(t.id), now()) then return 'too_far'; end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.rout_booking_within_limits(p_event_type uuid, p_host uuid, p_start timestamp with time zone, p_hold uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  t public.booking_event_types%rowtype; zone text; wall timestamp; unit text; lim integer;
  ps timestamptz; pe timestamptz; n integer;
begin
  select * into t from public.booking_event_types where id = p_event_type;
  if t.limit_per_day is null and t.limit_per_week is null and t.limit_per_month is null then return true; end if;
  if greatest(1, t.resource_capacity) > 1 and exists (
      select 1 from public.bookings b where b.host_user_id = p_host and b.event_type_id = t.id and b.shared_slot
        and b.start_utc = p_start and b.status in ('held','pending_payment','requested','confirmed')) then
    return true;
  end if;
  zone := public.rout_booking_zone(t.rules_timezone, p_host);
  wall := p_start at time zone zone;
  foreach unit in array array['day', 'week', 'month'] loop
    lim := case unit when 'day' then t.limit_per_day when 'week' then t.limit_per_week else t.limit_per_month end;
    continue when lim is null;
    ps := date_trunc(unit, wall) at time zone zone;
    pe := (date_trunc(unit, wall) + ('1 ' || unit)::interval) at time zone zone;
    select count(*) into n from (
      select case when b.shared_slot then 'S' || b.start_utc::text else b.id::text end
      from public.bookings b where b.host_user_id = p_host and b.event_type_id = t.id
        and b.status in ('held','pending_payment','requested','confirmed') and b.start_utc >= ps and b.start_utc < pe
      union
      select case when x.shared_slot then 'S' || x.start_utc::text else 'H' || x.hold_id::text end
      from public.booking_holds x where x.host_user_id = p_host and x.event_type_id = t.id and x.expires_at > now()
        and x.hold_id is distinct from p_hold and x.start_utc >= ps and x.start_utc < pe) keys;
    if n >= lim then return false; end if;
  end loop;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.rout_broadcast_event_allowed(p_owner uuid, p_event uuid, p_space text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare h text;
begin
 if p_owner is distinct from public.rout_current_user_id() then return false;end if;
 if p_space='root' then select username into h from public.profiles where id=p_owner;
 elsif p_space='alias' then select handle into h from public.alias_profiles where user_id=p_owner;
 else return false;end if;
 if h is null or not exists(select 1 from public.rout_qa_owner(h,p_space) where owner_id=p_owner) then return false;end if;
 return exists(select 1 from public.ephemeral_statuses where id=p_event and user_id=p_owner and space=p_space and status_type='micro_text' and expires_at>now())
 or exists(select 1 from public.profile_questions where id=p_event and owner_id=p_owner and space=p_space and published and not is_quarantined and answer is not null and story_until>now());
end $function$

CREATE OR REPLACE FUNCTION public.rout_card_token_use(n text, exp timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare inserted integer;
begin
  if n is null or n !~ '^[A-Za-z0-9_-]{22}$' or exp is null or exp <= now()
     or exp > now() + interval '60 seconds' then
    insert into public.audit_logs(event) values ('qr_expired');
    return false;
  end if;
  delete from public.used_nonces where expires_at < now() - interval '5 minutes';
  insert into public.used_nonces(nonce, expires_at) values(n, exp) on conflict do nothing;
  get diagnostics inserted = row_count;
  insert into public.audit_logs(event) values(case when inserted = 1 then 'qr_verified' else 'qr_replayed' end);
  return inserted = 1;
end $function$

CREATE OR REPLACE FUNCTION public.rout_claim_agent_workspace(p_token_hash text)
 RETURNS TABLE(workspace_id uuid, slug text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_uid uuid := public.rout_current_user_id();
  v_claim public.agent_workspace_claims%rowtype;
  v_slug text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_claim from public.agent_workspace_claims c where c.token_hash = p_token_hash for update;
  if not found then raise exception 'claim_not_found'; end if;
  if v_claim.claimed_at is not null then raise exception 'claim_used'; end if;
  if v_claim.expires_at <= now() then raise exception 'claim_expired'; end if;

  insert into public.workspace_members (workspace_id, user_id, role)
  values (v_claim.workspace_id, v_uid, 'owner')
  on conflict on constraint workspace_members_pkey do update set role = 'owner';
  update public.agent_workspace_claims c
     set claimed_at = now(), claimed_by = v_uid
   where c.workspace_id = v_claim.workspace_id;
  select w.slug into v_slug from public.workspaces w where w.id = v_claim.workspace_id;
  return query select v_claim.workspace_id, v_slug;
end;
$function$

CREATE OR REPLACE FUNCTION public.rout_claim_agent_workspace_v2(p_hash text)
 RETURNS TABLE(workspace_id uuid, slug text, pending_apps jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_uid uuid := public.rout_current_user_id(); v_claim public.agent_workspace_claims%rowtype; v_slug text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_claim from public.agent_workspace_claims c
   where c.token_hash = p_hash or c.code_hash = p_hash for update;
  if not found then raise exception 'claim_not_found'; end if;
  if v_claim.claimed_at is not null then raise exception 'claim_used'; end if;
  if v_claim.expires_at <= now() then raise exception 'claim_expired'; end if;

  insert into public.workspace_members (workspace_id, user_id, role)
  values (v_claim.workspace_id, v_uid, 'owner')
  on conflict on constraint workspace_members_pkey do update set role = 'owner';
  update public.agent_workspace_claims c
     set claimed_at = now(), claimed_by = v_uid, pending_apps = '[]'::jsonb
   where c.workspace_id = v_claim.workspace_id;
  update public.workspace_profile_drafts d set updated_by = v_uid where d.workspace_id = v_claim.workspace_id;
  if v_claim.sandbox_id is not null then
    update public.agent_sandboxes s set revoked_at = now() where s.id = v_claim.sandbox_id;
  end if;
  select w.slug into v_slug from public.workspaces w where w.id = v_claim.workspace_id;
  return query select v_claim.workspace_id, v_slug, v_claim.pending_apps;
end; $function$

CREATE OR REPLACE FUNCTION public.rout_entitlement_redeem_plus(p_user uuid, p_workspace uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v uuid;
begin
  if not exists (select 1 from public.workspace_members m
                  where m.workspace_id = p_workspace and m.user_id = p_user and m.role = 'owner') then
    return 'forbidden';
  end if;
  update public.entitlement_overrides o
     set value = ((case when o.value ~ '^[0-9]{1,6}$' then o.value::int else 0 end) - 1)::text
   where o.scope_type = 'user' and o.scope_id = p_user and o.entitlement_key = 'INCLUDED_PLUS_WORKSPACE'
     and (case when o.value ~ '^[0-9]{1,6}$' then o.value::int else 0 end) > 0
  returning o.id into v;
  if v is null then return 'no_credit'; end if;
  insert into public.entitlement_overrides (scope_type, scope_id, entitlement_key, value, granted_by)
  values ('workspace', p_workspace, 'WORKSPACE_PLAN', 'plus', 'user:' || p_user::text)
  on conflict (scope_type, scope_id, entitlement_key) do update set value = 'plus';
  return 'ok';
end $function$

CREATE OR REPLACE FUNCTION public.rout_ephemeral_vault_commit(p_vault_id uuid, p_vault_hash text, p_name text, p_slug text, p_blob text, p_key_id text)
 RETURNS TABLE(workspace_id uuid, slug text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_uid uuid := public.rout_current_user_id(); v_vault public.ephemeral_vaults%rowtype; v_ws uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_vault from public.ephemeral_vaults v where v.vault_id = p_vault_id for update;
  if not found then raise exception 'vault_not_found'; end if;
  if v_vault.expires_at <= now() then raise exception 'vault_expired'; end if;
  if v_vault.vault_hash <> p_vault_hash then raise exception 'vault_proof_invalid'; end if;
  if exists (select 1 from public.workspaces w where w.slug = lower(p_slug)) then raise exception 'slug_taken'; end if;

  insert into public.workspaces (name, slug, plan, encrypted_config, encrypted_config_key_id)
  values (p_name, lower(p_slug), 'free', p_blob, p_key_id)
  returning id into v_ws;
  insert into public.workspace_members (workspace_id, user_id, role) values (v_ws, v_uid, 'owner');
  delete from public.ephemeral_vaults v where v.vault_id = p_vault_id;
  return query select v_ws, lower(p_slug);
end; $function$

CREATE OR REPLACE FUNCTION public.rout_ephemeral_vault_create(p_vault_id uuid, p_key_hash text, p_vault_hash text, p_payload text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_sandbox uuid; v_open integer; v_now timestamptz := now();
begin
  select s.id into v_sandbox from public.agent_sandboxes s
   where s.key_hash = p_key_hash and s.revoked_at is null and s.expires_at > v_now;
  if v_sandbox is null then raise exception 'sandbox_invalid'; end if;
  perform pg_advisory_xact_lock(hashtext('ephemeral_vault:' || v_sandbox::text));
  delete from public.ephemeral_vaults v where v.expires_at <= v_now;
  select count(*) into v_open from public.ephemeral_vaults v where v.sandbox_id = v_sandbox;
  if v_open >= 5 then raise exception 'vault_quota_reached'; end if;
  insert into public.ephemeral_vaults (vault_id, vault_hash, encrypted_payload, sandbox_id, created_at, expires_at)
  values (p_vault_id, p_vault_hash, p_payload, v_sandbox, v_now, v_now + interval '1 hour');
  return v_now + interval '1 hour';
end; $function$

CREATE OR REPLACE FUNCTION public.rout_forwarding_send_check(p_user uuid, p_recipient text, p_per_10min integer, p_per_day integer, p_per_recipient_day integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_recipient text := pg_catalog.lower(pg_catalog.btrim(coalesce(p_recipient, ''))); r_recent int; r_daily int; r_rcpt int;
begin
  if p_user is null or pg_catalog.length(v_recipient) not between 3 and 320 or pg_catalog.strpos(v_recipient, '@') = 0
     or p_per_10min not between 1 and 100 or p_per_day not between 1 and 100 or p_per_recipient_day not between 1 and 100 then
    raise exception 'invalid forwarding check' using errcode = '22023';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('rout_fwd:' || p_user::text, 0));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('rout_fwd_rcpt:' || v_recipient, 0));
  select pg_catalog.count(*) filter (where s.sent_at > pg_catalog.now() - interval '10 minutes'),
         pg_catalog.count(*) filter (where s.sent_at > pg_catalog.now() - interval '1 day')
    into r_recent, r_daily
    from public.forwarding_confirmation_sends s where s.user_id = p_user;
  select pg_catalog.count(*) into r_rcpt from public.forwarding_confirmation_sends s
   where pg_catalog.lower(s.recipient) = v_recipient and s.sent_at > pg_catalog.now() - interval '1 day';
  if r_recent >= p_per_10min or r_daily >= p_per_day then return 'rate_limited_user'; end if;
  if r_rcpt >= p_per_recipient_day then return 'rate_limited_recipient'; end if;
  insert into public.forwarding_confirmation_sends (user_id, recipient) values (p_user, v_recipient);
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.rout_gift_card_activate(p_gift uuid, p_reference text, p_max_redemptions integer, p_expires_at timestamp with time zone, p_paid_cents integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare g public.gift_cards;
begin
  select * into g from public.gift_cards where id = p_gift for update;
  if not found then return pg_catalog.jsonb_build_object('outcome', 'not_found'); end if;
  if p_paid_cents is not null and p_paid_cents <> g.amount_cents then
    return pg_catalog.jsonb_build_object('outcome', 'amount_mismatch');
  end if;
  if coalesce(p_max_redemptions, 1) not between 1 and 10000 then
    raise exception 'invalid redemption cap' using errcode = '22023';
  end if;
  if not (g.status = 'pending'
          or (g.status = 'paid' and not exists (select 1 from public.promo_codes c where c.code = g.code))) then
    return pg_catalog.jsonb_build_object('outcome', 'duplicate');
  end if;
  update public.gift_cards
     set status = 'paid', paid_at = pg_catalog.now(),
         fulfilment_status = case when physical_delivery then 'pending_print' else fulfilment_status end,
         stripe_reference = coalesce(p_reference, stripe_reference), updated_at = pg_catalog.now()
   where id = p_gift
  returning * into g;
  insert into public.promo_codes (code, label, percent_off, amount_off_cents, max_redemptions, expires_at, active)
  values (g.code, 'Cadeaubon', 0, g.amount_cents, coalesce(p_max_redemptions, 1), p_expires_at, true)
  on conflict (code) do nothing;
  return pg_catalog.jsonb_build_object('outcome', 'activated', 'card', pg_catalog.to_jsonb(g));
end $function$

CREATE OR REPLACE FUNCTION public.rout_hw_consume_challenge(hid uuid, nh text)
 RETURNS TABLE(public_key text, key_alg text, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
begin
  if public.rout_card_status_by_hardware(hid) is distinct from 'active' then return; end if;
  delete from public.hardware_challenges c where c.nonce_hash = nh and c.hardware_id = hid and c.expires_at > now();
  if not found then return; end if;
  return query select k.public_key, k.key_alg, k.status from public.physical_keys k
    where k.hardware_id = hid and k.status = 'active';
end $function$

CREATE OR REPLACE FUNCTION public.rout_identity_label_put(p_account text, p_provider text, p_label text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
begin
  if p_account is null or pg_catalog.length(p_account) > 80 or p_provider is null or p_provider !~ '^[A-Za-z0-9_.:-]{1,40}$'
     or p_label is null or pg_catalog.length(p_label) not between 1 and 200 then
    raise exception 'invalid label' using errcode = '22023';
  end if;
  if not public.rout_identity_account_visible(p_account) then return false; end if;
  insert into public.identity_labels (account_id, provider, label) values (p_account, p_provider, p_label)
  on conflict (account_id) do update set label = excluded.label, updated_at = pg_catalog.now();
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.rout_integration_switch_set(p_provider text, p_mode text, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
begin
  if not public.rout_caller_has_admin_permission('manage_integrations') then
    raise exception 'admin only' using errcode = '42501';
  end if;
  if p_provider is null or p_provider !~ '^[a-z0-9_-]{1,40}$' or p_mode not in ('on', 'paused', 'off')
     or coalesce(pg_catalog.length(p_note), 0) > 500 then
    raise exception 'invalid integration switch' using errcode = '22023';
  end if;
  insert into public.platform_integration_switches (provider, mode, note, updated_by, updated_at)
  values (p_provider, p_mode, p_note, public.rout_current_user_id(), pg_catalog.now())
  on conflict (provider) do update set mode = excluded.mode, note = excluded.note,
    updated_by = excluded.updated_by, updated_at = pg_catalog.now();
end $function$

CREATE OR REPLACE FUNCTION public.rout_lead_capture_insert(p_handle text, p_name text, p_email text, p_message text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_handle text := pg_catalog.lower(pg_catalog.btrim(coalesce(p_handle, ''))); v_id uuid;
begin
  if pg_catalog.length(v_handle) not between 1 and 64
     or coalesce(pg_catalog.length(p_name), 0) > 120
     or p_email is null or pg_catalog.length(p_email) not between 3 and 254 or pg_catalog.strpos(p_email, '@') = 0
     or coalesce(pg_catalog.length(p_message), 0) > 1000 then
    raise exception 'invalid lead' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.profiles p
     cross join lateral pg_catalog.jsonb_array_elements(case when pg_catalog.jsonb_typeof(p.blocks) = 'array' then p.blocks else '[]'::jsonb end) b(el)
     where pg_catalog.lower(p.username) = v_handle and b.el->>'kind' = 'contact_form'
       and coalesce(b.el->'hidden', 'false'::jsonb) <> 'true'::jsonb) then
    raise exception 'no contact form' using errcode = 'P0002';
  end if;
  insert into public.lead_captures (handle, name, email, message) values (v_handle, p_name, p_email, p_message)
  returning id into v_id;
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.rout_link_click_record(p_handle text, p_block_id text, p_label text, p_space text, p_visitor_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_handle text := pg_catalog.lower(pg_catalog.btrim(coalesce(p_handle, '')));
  v_owner uuid;
begin
  if pg_catalog.length(v_handle) not between 1 and 64
     or p_block_id is null or pg_catalog.length(p_block_id) not between 1 and 64
     or coalesce(pg_catalog.length(p_label), 0) > 120
     or p_space not in ('root', 'alias')
     or (p_visitor_hash is not null and pg_catalog.length(p_visitor_hash) > 128) then
    raise exception 'invalid link click' using errcode = '22023';
  end if;
  select p.id into v_owner from public.profiles p where pg_catalog.lower(p.username) = v_handle limit 1;
  if v_owner is null then
    select a.user_id into v_owner from public.alias_profiles a where pg_catalog.lower(a.handle) = v_handle limit 1;
  end if;
  if v_owner is null then return false; end if;
  insert into public.profile_link_clicks (profile_user_id, handle, block_id, label, space, visitor_hash)
  values (v_owner, v_handle, p_block_id, nullif(p_label, ''), p_space, p_visitor_hash);
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.rout_notify_omni_job()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 if new.status='queued' and (tg_op='INSERT' or old.status is distinct from new.status) then
  perform pg_notify('new_omni_job', json_build_object('id',new.id)::text);
 end if;
 if tg_op='INSERT' or old.status is distinct from new.status then
  perform pg_notify('omni_job_changed',json_build_object('id',new.id,'userId',new.user_id)::text);
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.rout_oauth_admin_app_decide(p_id uuid, p_action text)
 RETURNS TABLE(client_id text, name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_client text; v_name text; v_actor uuid := public.rout_current_user_id();
begin
  if not public.rout_caller_has_admin_permission('review_apps') then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_action not in ('approve', 'reject', 'block', 'unblock') then raise exception 'invalid_action' using errcode = '22023'; end if;
  select c.client_id, c.name into v_client, v_name from public.oauth_clients c where c.id = p_id for update;
  if not found then return; end if;
  if p_action in ('approve', 'reject') then
    update public.oauth_client_verification_requests v
       set status = case when p_action = 'approve' then 'verified' else 'rejected' end,
           reviewed_by = v_actor, reviewed_at = now()
     where v.client_id = v_client and v.status = 'pending';
    if not found then
      insert into public.oauth_client_verification_requests (client_id, requested_by, note, status, reviewed_by, reviewed_at)
      values (v_client, v_actor, 'Beslissing door admin', case when p_action = 'approve' then 'verified' else 'rejected' end, v_actor, now());
    end if;
  else
    update public.oauth_clients c set status = case when p_action = 'block' then 'disabled' else 'active' end where c.id = p_id;
    if p_action = 'block' then
      update public.oauth_auth_codes a set consumed_at = now() where a.client_id = v_client and a.consumed_at is null;
    end if;
  end if;
  return query select v_client, v_name;
end $function$

CREATE OR REPLACE FUNCTION public.rout_oauth_code_consume(p_code_hash text, p_client text, p_redirect text, p_verifier text)
 RETURNS TABLE(result text, user_id uuid, scopes text[], nonce text, acr text, auth_time timestamp with time zone, rich_identity boolean, redirect_uri text, has_pkce boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare r public.oauth_auth_codes%rowtype;
begin
  update public.oauth_auth_codes c set consumed_at = now()
   where c.code_hash = p_code_hash and c.consumed_at is null and c.expires_at > now()
  returning c.* into r;
  if not found then
    return query select 'invalid'::text, null::uuid, null::text[], null::text, null::text, null::timestamptz, null::boolean, null::text, null::boolean;
    return;
  end if;
  if r.client_id is distinct from p_client then
    return query select 'client_mismatch'::text, null::uuid, null::text[], null::text, null::text, null::timestamptz, null::boolean, null::text, null::boolean;
    return;
  end if;
  if r.redirect_uri is distinct from p_redirect then
    return query select 'redirect_mismatch'::text, null::uuid, null::text[], null::text, null::text, null::timestamptz, null::boolean, r.redirect_uri, null::boolean;
    return;
  end if;
  if coalesce(r.code_challenge, '') <> '' then
    if coalesce(p_verifier, '') = '' then
      return query select 'pkce_missing'::text, null::uuid, null::text[], null::text, null::text, null::timestamptz, null::boolean, null::text, true;
      return;
    end if;
    if public.rout_oauth_b64url_sha256(p_verifier) <> r.code_challenge then
      return query select 'pkce_failed'::text, null::uuid, null::text[], null::text, null::text, null::timestamptz, null::boolean, null::text, true;
      return;
    end if;
  end if;
  return query select 'ok'::text, r.user_id, r.scopes, r.nonce, r.acr, r.auth_time, r.rich_identity, r.redirect_uri,
    coalesce(r.code_challenge, '') <> '';
end $function$

CREATE OR REPLACE FUNCTION public.rout_oauth_code_issue(p_code_hash text, p_client text, p_redirect text, p_scopes text[], p_challenge text, p_nonce text, p_acr text, p_rich boolean, p_ttl_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_user uuid := public.rout_current_user_id();
begin
  if v_user is null then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_code_hash is null or pg_catalog.length(p_code_hash) not between 20 and 200 then return false; end if;
  if not exists (select 1 from public.oauth_clients c where c.client_id = p_client and c.status = 'active'
                   and p_redirect = any (c.redirect_uris)) then
    return false;
  end if;
  insert into public.oauth_auth_codes (code_hash, client_id, user_id, redirect_uri, scopes, code_challenge,
    nonce, expires_at, acr, rich_identity)
  values (p_code_hash, p_client, v_user, p_redirect, coalesce(p_scopes, '{}'), coalesce(p_challenge, ''),
    p_nonce, now() + pg_catalog.make_interval(secs => least(greatest(coalesce(p_ttl_seconds, 60), 1), 600)),
    p_acr, coalesce(p_rich, false));
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.rout_oauth_consent_grant(p_client text, p_scopes text[])
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_user uuid := public.rout_current_user_id();
begin
  if v_user is null then raise exception 'forbidden' using errcode = '42501'; end if;
  if not exists (select 1 from public.oauth_clients c where c.client_id = p_client and c.status = 'active') then
    return false;
  end if;
  insert into public.oauth_consents (user_id, client_id, scopes)
  values (v_user, p_client, coalesce(p_scopes, '{}'))
  on conflict (user_id, client_id) do update set
    scopes = case when public.oauth_consents.revoked_at is null
      then array(select distinct x from unnest(public.oauth_consents.scopes || excluded.scopes) as x order by x)
      else excluded.scopes end,
    granted_at = now(), revoked_at = null;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.rout_oauth_debug_log(p_client text, p_endpoint text, p_outcome text, p_error text, p_detail jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
begin
  if p_endpoint not in ('authorize', 'token', 'userinfo') or p_outcome not in ('success', 'error')
     or p_client is null or pg_catalog.length(p_client) > 100
     or pg_catalog.octet_length(coalesce(p_detail, '{}'::jsonb)::text) > 4000
     or not exists (select 1 from public.oauth_clients c where c.client_id = p_client) then
    return;
  end if;
  insert into public.oauth_debug_events (client_id, endpoint, outcome, error_code, detail)
  values (p_client, p_endpoint, p_outcome, left(p_error, 100), coalesce(p_detail, '{}'::jsonb));
  if pg_catalog.random() < 0.02 then
    delete from public.oauth_debug_events e where e.created_at < now() - interval '7 days';
  end if;
end $function$

CREATE OR REPLACE FUNCTION public.rout_oauth_signing_key_rotate(p_kid text, p_public jsonb, p_sealed text, p_iv text, p_fingerprint text, p_alg text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_created timestamptz;
begin
  if p_kid is null or p_public is null or p_sealed is null or p_iv is null or p_alg is distinct from 'ES256'
     or p_public ? 'd' then
    raise exception 'invalid_signing_key' using errcode = '22023';
  end if;
  insert into public.oauth_signing_keys (kid, private_jwk, public_jwk, private_jwk_sealed, private_jwk_iv, kek_fingerprint, alg)
  values (p_kid, null, p_public, p_sealed, p_iv, p_fingerprint, p_alg)
  returning created_at into v_created;
  update public.oauth_signing_keys k set retired_at = now()
   where k.retired_at is null and k.kid <> p_kid and k.created_at <= v_created;
  return v_created;
end $function$

CREATE OR REPLACE FUNCTION public.rout_oauth_signing_keys_wipe(p_kids text[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare n integer;
begin
  update public.oauth_signing_keys k set private_jwk = null, private_jwk_sealed = null, private_jwk_iv = null
   where k.kid = any (p_kids) and (k.retired_at is not null or k.revoked_at is not null);
  get diagnostics n = row_count;
  return n;
end $function$

