CREATE OR REPLACE FUNCTION public.rout_oauth_verification_request(p_client text, p_note text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
