CREATE OR REPLACE FUNCTION public.rout_promo_admin_save(p_code text, p_label text, p_percent integer, p_amount integer, p_max_discount integer, p_max_redemptions integer, p_expires_at timestamp with time zone, p_overwrite boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
begin
  perform public.rout_require_admin();
  if p_code !~ '^[^[:space:]]{1,64}$' or coalesce(p_percent, 0) not between 0 and 100 or coalesce(p_amount, 0) < 0
     or (p_max_redemptions is not null and p_max_redemptions not between 1 and 100000) then
    raise exception 'invalid promo code' using errcode = '22023';
  end if;
  if p_overwrite then
    insert into public.promo_codes (code, label, percent_off, amount_off_cents, max_discount_cents, max_redemptions, expires_at, active)
    values (p_code, p_label, coalesce(p_percent, 0), coalesce(p_amount, 0), p_max_discount, p_max_redemptions, p_expires_at, true)
    on conflict (code) do update set label = excluded.label, percent_off = excluded.percent_off,
      amount_off_cents = excluded.amount_off_cents, max_discount_cents = excluded.max_discount_cents,
      max_redemptions = excluded.max_redemptions, expires_at = excluded.expires_at, active = true, updated_at = pg_catalog.now();
    return true;
  end if;
  insert into public.promo_codes (code, label, percent_off, amount_off_cents, max_discount_cents, max_redemptions, expires_at, active)
  values (p_code, p_label, coalesce(p_percent, 0), coalesce(p_amount, 0), p_max_discount, p_max_redemptions, p_expires_at, true)
  on conflict (code) do nothing;
  return found;
end $function$

CREATE OR REPLACE FUNCTION public.rout_promo_redeem(p_code text)
 RETURNS TABLE(redeemed_count integer, max_redemptions integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_count int; v_max int;
begin
  update public.promo_codes c
     set redeemed_count = c.redeemed_count + 1,
         last_redeemed_at = pg_catalog.now(),
         active = case when c.max_redemptions is not null and c.redeemed_count + 1 >= c.max_redemptions
                       then false else c.active end,
         updated_at = pg_catalog.now()
   where c.code = p_code and c.active
     and (c.expires_at is null or c.expires_at > pg_catalog.now())
     and (c.max_redemptions is null or c.redeemed_count < c.max_redemptions)
  returning c.redeemed_count, c.max_redemptions into v_count, v_max;
  if v_count is null then
    insert into public.promo_code_events (code, event, detail) values (p_code, 'exhausted', 'claim geweigerd: niet meer geldig');
    return;
  end if;
  insert into public.promo_code_events (code, event, detail) values (p_code, 'redeemed', 'gebruik #' || v_count);
  if v_max is not null and v_count >= v_max then
    insert into public.promo_code_events (code, event, detail) values (p_code, 'exhausted', 'maximum bereikt');
  end if;
  redeemed_count := v_count; max_redemptions := v_max;
  return next;
end $function$

CREATE OR REPLACE FUNCTION public.rout_protocol_append(p_stream text, p_seq bigint, p_prev text, p_hash text, p_author text, p_kind text, p_cap_id text, p_event jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare head_hash text; inserted int;
begin
  if p_seq > 0 then
    select hash into head_hash from public.protocol_events where stream_id = p_stream and seq = p_seq - 1;
    if head_hash is null then
      if not exists (select 1 from public.protocol_events where stream_id = p_stream) then return 'unknown_stream'; end if;
      return 'chain_broken';
    end if;
    if head_hash <> p_prev then return 'chain_broken'; end if;
  end if;
  insert into public.protocol_events (stream_id, seq, prev_hash, hash, author_did, kind, cap_id, event)
  values (p_stream, p_seq, p_prev, p_hash, p_author, p_kind, p_cap_id, p_event)
  on conflict do nothing;
  get diagnostics inserted = row_count;
  return case when inserted = 1 then 'ok' else 'conflict' end;
end $function$

CREATE OR REPLACE FUNCTION public.rout_protocol_dpop_spend(p_jkt text, p_jti text, p_expires_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare inserted int;
begin
  delete from public.protocol_dpop_jti where expires_at < now() - interval '1 minute';
  insert into public.protocol_dpop_jti (jkt, jti, expires_at)
  values (p_jkt, p_jti, least(p_expires_at, now() + interval '5 minutes'))
  on conflict do nothing;
  get diagnostics inserted = row_count;
  return inserted = 1;
end $function$

CREATE OR REPLACE FUNCTION public.rout_purge_unclaimed_agent_workspaces()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_ids uuid[];
begin
  select coalesce(array_agg(c.workspace_id), '{}') into v_ids
    from (select workspace_id from public.agent_workspace_claims
           where claimed_at is null and expires_at <= now()
           order by expires_at
           limit 500
           for update skip locked) c;
  if cardinality(v_ids) > 0 then
    delete from public.oauth_clients where workspace_id = any (v_ids);
    delete from public.tracked_qrs where workspace_id = any (v_ids);
    delete from public.bookings where workspace_id = any (v_ids);
    delete from public.workspace_transfers where workspace_id = any (v_ids);
    delete from public.workspaces where id = any (v_ids); -- drafts and claims cascade
  end if;
  -- Expired sandbox keys (and sandboxes that never created a workspace).
  delete from public.agent_sandboxes where expires_at <= now();
  return cardinality(v_ids);
end;
$function$

CREATE OR REPLACE FUNCTION public.rout_qa_charge(p_recipient uuid, p_abuse_key text, p_net text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_id bigint;
  v_net text := case when p_net ~ '^[0-9a-f]{64}$' then p_net end;
  v_score integer;
  v_start timestamptz := now() + make_interval(mins => 720 + floor(random() * 2161)::int);
begin
  if p_abuse_key is null or p_abuse_key !~ '^[0-9a-f]{64}$' then return; end if;
  insert into public.qa_trust_charges (recipient_id, sender_key, muter_net) values (p_recipient, p_abuse_key, v_net)
  on conflict (recipient_id, sender_key) where sender_key is not null do nothing
  returning id into v_id;
  if v_id is null then return; end if;
  if exists (select 1 from public.qa_trust_charges c
              where c.sender_key = p_abuse_key and c.id <> v_id and c.charged_at > now() - interval '24 hours') then
    return;
  end if;
  if v_net is not null and exists (select 1 from public.qa_trust_charges c
              where c.sender_key = p_abuse_key and c.id <> v_id and c.muter_net = v_net
                and c.charged_at > now() - interval '7 days') then
    return;
  end if;
  insert into public.qa_guest_trust as g (sender_key, trust_score) values (p_abuse_key, 80)
  on conflict (sender_key) do update set trust_score = greatest(0, g.trust_score - 20), updated_at = now()
  returning g.trust_score into v_score;
  if v_score < 50 then
    update public.qa_guest_trust g
       set ban_starts_at = v_start, ban_until = v_start + interval '7 days', updated_at = now()
     where g.sender_key = p_abuse_key and (g.ban_until is null or g.ban_until < now());
  end if;
end $function$

CREATE OR REPLACE FUNCTION public.rout_qa_maintenance()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_abuse int; v_quar int; v_charges int; v_healed int; v_users int; v_rl int;
begin
  update public.profile_questions set abuse_key = null, abuse_key_until = null
   where abuse_key is not null and abuse_key_until < now();
  get diagnostics v_abuse = row_count;
  delete from public.profile_questions
   where is_quarantined and quarantine_reason in ('local_mute', 'global_ban') and created_at < now() - interval '30 days';
  get diagnostics v_quar = row_count;
  delete from public.qa_trust_charges where charged_at < now() - interval '90 days';
  get diagnostics v_charges = row_count;
  update public.qa_guest_trust set trust_score = least(100, trust_score + 10), updated_at = now()
   where trust_score < 100 and updated_at < now() - interval '7 days';
  get diagnostics v_healed = row_count;
  delete from public.qa_guest_trust where trust_score >= 100 and (ban_until is null or ban_until < now());
  update public.users set trust_score = least(100, trust_score + 10), trust_healed_at = now()
   where trust_score < 100 and coalesce(trust_healed_at, '-infinity'::timestamptz) < now() - interval '7 days';
  get diagnostics v_users = row_count;
  delete from public.rate_limits where window_start < now() - interval '1 day';
  get diagnostics v_rl = row_count;
  return jsonb_build_object('abuseKeysExpired', v_abuse, 'quarantineDeleted', v_quar, 'chargesExpired', v_charges,
                            'guestsHealed', v_healed, 'usersHealed', v_users, 'rateLimitsDeleted', v_rl);
end $function$

CREATE OR REPLACE FUNCTION public.rout_qa_mute_by_message(p_message_id uuid, p_muter_net text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_me uuid := public.rout_current_user_id();
  q record;
  v_action uuid;
begin
  if v_me is null then return false; end if;
  select owner_id, space, sender_key, sender_acct_key, abuse_key, abuse_key_until into q
    from public.profile_questions where id = p_message_id;
  if not found or q.owner_id <> v_me then return false; end if;
  if exists (select 1 from public.qa_mute_actions a where a.recipient_id = v_me and a.source_question_id = p_message_id) then
    return true;
  end if;
  insert into public.qa_mute_actions (recipient_id, source_question_id) values (v_me, p_message_id) returning id into v_action;
  if q.sender_key is not null then
    insert into public.shadow_mutes (recipient_id, action_id, muted_sender_key, space) values (v_me, v_action, q.sender_key, q.space);
  end if;
  if q.sender_acct_key is not null and q.sender_acct_key is distinct from q.sender_key then
    insert into public.shadow_mutes (recipient_id, action_id, muted_sender_key, space) values (v_me, v_action, q.sender_acct_key, q.space);
  end if;
  if q.abuse_key is not null and q.abuse_key_until > now() then
    perform public.rout_qa_charge(v_me, q.abuse_key, p_muter_net);
  end if;
  update public.profile_questions
     set is_quarantined = true, quarantine_reason = 'muted_by_owner', published = false
   where id = p_message_id;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.rout_qa_submit(p_handle text, p_space text, p_body text, p_device_base text, p_acct_base text, p_abuse_now text, p_abuse_prev text, p_masked boolean)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  o record;
  v_sender uuid := public.rout_current_user_id();
  v_dev text;
  v_acct text;
  v_abuse text := case when p_abuse_now ~ '^[0-9a-f]{64}$' then p_abuse_now end;
  v_abuse_prev text := case when p_abuse_prev ~ '^[0-9a-f]{64}$' then p_abuse_prev end;
  v_prompt text;
  v_local boolean;
  v_global boolean;
  v_reason text;
  v_level text;
begin
  if p_space not in ('root', 'alias') then return 'not_found'; end if;
  if p_body is null or char_length(p_body) not between 1 and 300 then return 'invalid'; end if;
  select * into o from public.rout_qa_owner(p_handle, p_space);
  if o.owner_id is null or not coalesce((o.prefs ->> 'questionsEnabled')::boolean, false) then return 'not_found'; end if;
  v_level := coalesce(o.prefs->>'qaAudience', 'members_only');
  if v_level not in ('public_unrestricted', 'members_only', 'verified_only') then return 'not_found'; end if;
  if v_level <> 'public_unrestricted' and v_sender is null then return 'not_found'; end if;
  if v_level = 'verified_only' and not exists (select 1 from public.profiles where id=v_sender and verified is true) then return 'not_found'; end if;
  if exists (select 1 from public.users where id=o.owner_id and qa_permission_level='disabled') then return 'not_found'; end if;
  if exists (select 1 from public.users where id=o.owner_id and qa_permission_level='verified_only') and not exists (select 1 from public.profiles where id=v_sender and verified is true) then return 'not_found'; end if;
  if exists (select 1 from public.users where id=o.owner_id and qa_permission_level='members_only') and v_sender is null then return 'not_found'; end if;
  v_prompt := nullif(left(btrim(coalesce(
    case when o.prefs ->> 'qaPrompt' = 'custom' then o.prefs ->> 'qaPromptCustom' end,
    o.prefs ->> 'qaPrompt')), 120), '');

  v_dev := public.rout_qa_scope_key(p_device_base, o.owner_id, p_space);
  v_acct := case when v_sender is not null then public.rout_qa_scope_key(p_acct_base, o.owner_id, p_space) end;

  -- Both checks always run, whatever the first one finds.
  v_local := exists (select 1 from public.shadow_mutes m
                      where m.recipient_id = o.owner_id
                        and (m.space is null or m.space = p_space)
                        and ((m.muted_sender_key is not null and m.muted_sender_key in (v_dev, v_acct))
                          or (v_sender is not null and m.space is null and m.muted_sender_id = v_sender)));
  v_global := exists (select 1 from public.users u
                       where u.id = v_sender and u.global_shadow_ban_starts_at <= now() and u.global_shadow_ban_until > now())
           or exists (select 1 from public.profiles p where p.id = v_sender and coalesce(p.is_shadowbanned, false))
           or exists (select 1 from public.qa_guest_trust g
                       where g.sender_key in (v_abuse, v_abuse_prev) and g.ban_starts_at <= now() and g.ban_until > now());
  v_reason := case when v_local then 'local_mute' when v_global then 'global_ban' end;

  insert into public.profile_questions
    (owner_id, space, body, prompt, sender_key, sender_acct_key, abuse_key, abuse_key_until,
     is_quarantined, quarantine_reason, style_masked, visible_after)
  values
    (o.owner_id, p_space, p_body, v_prompt, v_dev, v_acct, v_abuse,
     case when v_abuse is not null then now() + interval '7 days' end,
     v_reason is not null, v_reason, coalesce(p_masked, false),
     now() + make_interval(secs => 120 + floor(random() * 481)::int));
  return 'ok';
end $function$

CREATE OR REPLACE FUNCTION public.rout_qa_unmute(p_action_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_me uuid := public.rout_current_user_id();
  v_source uuid;
begin
  if v_me is null then return false; end if;
  delete from public.qa_mute_actions where id = p_action_id and recipient_id = v_me
  returning source_question_id into v_source;
  if not found then return false; end if;
  if v_source is not null then
    update public.profile_questions
       set is_quarantined = false, quarantine_reason = null
     where id = v_source and owner_id = v_me and quarantine_reason = 'muted_by_owner';
  end if;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.rout_rate_limit_check_and_increment(p_bucket text, p_window_sec integer)
 RETURNS TABLE(hits integer, prev integer, now_ms bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_now timestamptz := pg_catalog.now();
  v_start timestamptz;
  v_hits int;
  v_prev int;
begin
  if p_bucket is null or p_bucket !~ '^[^[:space:]]{1,200}$' or p_window_sec is null or p_window_sec not between 1 and 604800 then
    raise exception 'invalid rate limit' using errcode = '22023';
  end if;
  v_start := pg_catalog.to_timestamp(pg_catalog.floor(extract(epoch from v_now) / p_window_sec) * p_window_sec);
  insert into public.rate_limits as r (bucket, window_start, hits) values (p_bucket, v_start, 1)
  on conflict (bucket, window_start) do update set hits = r.hits + 1
  returning r.hits into v_hits;
  select r.hits into v_prev from public.rate_limits r
   where r.bucket = p_bucket and r.window_start = v_start - pg_catalog.make_interval(secs => p_window_sec);
  delete from public.rate_limits r
   where r.bucket = p_bucket and r.window_start < v_start - pg_catalog.make_interval(secs => p_window_sec);
  if pg_catalog.random() < 0.02 then
    delete from public.rate_limits r
     where r.ctid = any (array(select x.ctid from public.rate_limits x
                                where x.window_start < v_now - interval '1 day' limit 500));
  end if;
  hits := v_hits;
  prev := coalesce(v_prev, 0);
  now_ms := (extract(epoch from v_now) * 1000)::bigint;
  return next;
end $function$

CREATE OR REPLACE FUNCTION public.rout_rate_limit_peek(p_bucket text, p_since_sec integer)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v int;
begin
  if p_bucket is null or p_bucket !~ '^[^[:space:]]{1,200}$' or p_since_sec is null or p_since_sec not between 1 and 604800 then
    raise exception 'invalid rate limit' using errcode = '22023';
  end if;
  select coalesce(sum(r.hits), 0)::int into v from public.rate_limits r
   where r.bucket = p_bucket and r.window_start > pg_catalog.now() - pg_catalog.make_interval(secs => p_since_sec);
  return v;
end $function$

CREATE OR REPLACE FUNCTION public.rout_record_signup_age(p_email text, p_dob date, p_parent_email text, p_token_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_id uuid; v_minor boolean;
begin
  select id into v_id from public.users
   where lower(email) = lower(p_email) and date_of_birth is null and created_at > now() - interval '15 minutes'
   limit 1;
  if v_id is null then return null; end if;
  v_minor := p_dob > (current_date - interval '16 years');
  update public.users
     set date_of_birth = p_dob,
         parent_email = case when v_minor then lower(p_parent_email) else null end,
         parent_consent_status = case when v_minor then 'pending'::public.parent_consent_status else 'none' end
   where id = v_id;
  if v_minor and p_token_hash is not null then
    insert into public.parent_authorizations (user_id, token, action_type, expires_at)
    values (v_id, p_token_hash, 'consent', now() + interval '30 days');
  end if;
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.rout_recovery_ceremony_delete()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare n int;
begin
  delete from public.recovery_ceremonies where user_id = public.rout_current_user_id();
  get diagnostics n = row_count;
  return n > 0;
end $function$

CREATE OR REPLACE FUNCTION public.rout_recovery_request_approve(p_id uuid, p_note text, p_token_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_admin uuid := public.rout_recovery_caller_admin();
  v_note  text := pg_catalog.left(nullif(pg_catalog.btrim(coalesce(p_note, '')), ''), 1000);
begin
  if v_admin is null then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_id is null or v_note is null or p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then
    return false;
  end if;
  update public.auth_recovery_requests r
     set status = 'approved', decided_at = pg_catalog.now(), decided_by = v_admin, decision_note = v_note,
         token_hash = p_token_hash, token_expires_at = pg_catalog.now() + pg_catalog.make_interval(hours => 24)
   where r.id = p_id and r.status = 'pending';
  if not found then
    return false;
  end if;
  perform public.rout_audit_insert(v_admin, (select u.email from public.users u where u.id = v_admin),
    'RECOVERY_REQUEST_APPROVED', null, 'recovery:' || p_id::text, null);
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.rout_recovery_request_deny(p_id uuid, p_note text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_admin uuid := public.rout_recovery_caller_admin();
  v_note  text := pg_catalog.left(nullif(pg_catalog.btrim(coalesce(p_note, '')), ''), 1000);
begin
  if v_admin is null then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_id is null then
    return false;
  end if;
  update public.auth_recovery_requests r
     set status = 'denied', decided_at = pg_catalog.now(), decided_by = v_admin, decision_note = v_note, token_hash = null
   where r.id = p_id and r.status in ('pending', 'approved');
  if not found then
    return false;
  end if;
  perform public.rout_audit_insert(v_admin, (select u.email from public.users u where u.id = v_admin),
    'RECOVERY_REQUEST_DENIED', null, 'recovery:' || p_id::text, null);
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.rout_recovery_request_file(p_email text, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_email text := pg_catalog.lower(pg_catalog.btrim(coalesce(p_email, '')));
  v_note  text := pg_catalog.left(nullif(pg_catalog.btrim(coalesce(p_note, '')), ''), 1000);
  v_user  text;
begin
  if pg_catalog.char_length(v_email) not between 3 and 254 or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    return;
  end if;
  select au.id::text into v_user from neon_auth."user" au where pg_catalog.lower(au.email) = v_email limit 1;
  if v_user is null or exists (select 1 from neon_auth.passkey k where k."userId" = v_user) then
    return;
  end if;
  insert into public.auth_recovery_requests (auth_user_id, email, note)
  values (v_user, v_email, v_note)
  on conflict do nothing;
end $function$

CREATE OR REPLACE FUNCTION public.rout_referral_claim(p_inviter uuid, p_invitee uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v uuid;
begin
  if p_inviter is null or p_invitee is null or p_inviter = p_invitee then return false; end if;
  if not exists (select 1 from public.users u where u.id = p_invitee and u.created_at > pg_catalog.now() - interval '24 hours') then
    return false;
  end if;
  insert into public.referrals (inviter_id, invitee_id) values (p_inviter, p_invitee)
  on conflict (invitee_id) do nothing returning id into v;
  return v is not null;
end $function$

CREATE OR REPLACE FUNCTION public.rout_require_admin()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v uuid := public.rout_current_user_id();
begin
  if v is null or not public.rout_has_role(v, 'admin') then
    raise exception 'admin required' using errcode = '42501';
  end if;
  return v;
end $function$

CREATE OR REPLACE FUNCTION public.rout_security_code_consume(p_user uuid, p_purpose text, p_code_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_user uuid := public.rout_current_user_id();
  v_row public.security_codes%rowtype;
begin
  if v_user is null or p_user is distinct from v_user or p_purpose is null or p_code_hash is null then return false; end if;
  select * into v_row from public.security_codes
   where user_id = v_user and purpose = p_purpose and consumed_at is null and expires_at > now()
   order by created_at desc limit 1 for update;
  if not found or v_row.attempts >= 5 then return false; end if;
  if v_row.code_hash is distinct from p_code_hash then
    update public.security_codes set attempts = attempts + 1 where id = v_row.id;
    return false;
  end if;
  update public.security_codes set consumed_at = now() where id = v_row.id and consumed_at is null;
  return found;
end $function$

CREATE OR REPLACE FUNCTION public.rout_security_code_issue(p_user uuid, p_purpose text, p_code_hash text, p_ttl_minutes integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_user uuid := public.rout_current_user_id();
begin
  if v_user is null or p_user is distinct from v_user then return 'no_context'; end if;
  if p_purpose is null or p_purpose not in ('merge', 'password', 'two_factor', 'workspace_convert',
       'delete_account', 'identity_link', 'step_up', 'step_up_sms', 'recovery')
     or p_code_hash is null or p_code_hash !~ '^[A-Za-z0-9+/]{43}=$'
     or p_ttl_minutes is null or p_ttl_minutes not between 1 and 15 then
    return 'invalid';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('rout.security_code:' || v_user::text || ':' || p_purpose, 0));
  if (select count(*) from public.security_codes
       where user_id = v_user and purpose = p_purpose and created_at > now() - interval '15 minutes') >= 5 then
    return 'rate_limited';
  end if;
  update public.security_codes set consumed_at = now()
   where user_id = v_user and purpose = p_purpose and consumed_at is null;
  insert into public.security_codes (user_id, purpose, code_hash, expires_at)
  values (v_user, p_purpose, p_code_hash, now() + make_interval(mins => p_ttl_minutes));
  return 'ok';
end $function$

CREATE OR REPLACE FUNCTION public.rout_security_code_purge()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare n integer;
begin
  delete from public.security_codes
   where expires_at < now() - interval '30 minutes' or consumed_at < now() - interval '30 minutes';
  get diagnostics n = row_count;
  return n;
end $function$

CREATE OR REPLACE FUNCTION public.rout_shadow_mute_trust()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_score integer;
  v_new integer;
  v_start timestamptz := now() + make_interval(mins => 720 + floor(random() * 2161)::int);
begin
  if new.muted_sender_id is not null then
    insert into public.qa_trust_charges (recipient_id, sender_user_id) values (new.recipient_id, new.muted_sender_id)
    on conflict (recipient_id, sender_user_id) where sender_user_id is not null do nothing;
    get diagnostics v_new = row_count;
    if v_new = 0 then return new; end if;
    update public.users u
       set trust_score = greatest(0, u.trust_score - 20)
     where u.id = new.muted_sender_id
     returning u.trust_score into v_score;
    if v_score is not null and v_score < 50 then
      update public.users u
         set global_shadow_ban_starts_at = v_start,
             global_shadow_ban_until = v_start + interval '7 days'
       where u.id = new.muted_sender_id
         and (u.global_shadow_ban_until is null or u.global_shadow_ban_until < now());
    end if;
  elsif new.muted_sender_key is not null then
    insert into public.qa_trust_charges (recipient_id, sender_key) values (new.recipient_id, new.muted_sender_key)
    on conflict (recipient_id, sender_key) where sender_key is not null do nothing;
    get diagnostics v_new = row_count;
    if v_new = 0 then return new; end if;
    insert into public.qa_guest_trust as g (sender_key, trust_score)
         values (new.muted_sender_key, 80)
    on conflict (sender_key) do update
         set trust_score = greatest(0, g.trust_score - 20), updated_at = now()
    returning g.trust_score into v_score;
    if v_score < 50 then
      update public.qa_guest_trust g
         set ban_starts_at = v_start, ban_until = v_start + interval '7 days', updated_at = now()
       where g.sender_key = new.muted_sender_key
         and (g.ban_until is null or g.ban_until < now());
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.rout_showcase_replace(p_handles text[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare h text; i int := 0;
begin
  if not public.rout_caller_is_admin() then
    raise exception 'admin only' using errcode = '42501';
  end if;
  if p_handles is null or coalesce(pg_catalog.array_length(p_handles, 1), 0) > 20 then
    raise exception 'invalid showcase list' using errcode = '22023';
  end if;
  foreach h in array p_handles loop
    if h is null or h !~ '^[a-z0-9._-]{1,64}$' then
      raise exception 'invalid showcase handle' using errcode = '22023';
    end if;
  end loop;
  delete from public.showcase_profiles where true;
  foreach h in array p_handles loop
    insert into public.showcase_profiles (handle, display_name, position, sort_order)
    values (h, h, i, i) on conflict (handle) do nothing;
    i := i + 1;
  end loop;
  return i;
end $function$

CREATE OR REPLACE FUNCTION public.rout_stateless_otp_issue(p_kind text, p_key text, p_code_hash text, p_payload text, p_ttl_sec integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_lock timestamptz;
begin
  if p_key is null or p_key !~ '^[0-9a-f]{64}$' or p_code_hash is null or p_code_hash !~ '^[0-9a-f]{64}$'
     or p_payload is null or pg_catalog.length(p_payload) not between 1 and 4000 then
    raise exception 'invalid code' using errcode = '22023';
  end if;
  if p_kind = 'login_code' then
    if p_ttl_sec is null or p_ttl_sec not between 60 and 900 then raise exception 'invalid code' using errcode = '22023'; end if;
    delete from public.login_codes where email_hash = p_key or expires_at < pg_catalog.now();
    insert into public.login_codes (email_hash, code_hash, link, expires_at, attempts)
    values (p_key, p_code_hash, p_payload, pg_catalog.now() + pg_catalog.make_interval(secs => p_ttl_sec), 0);
    return 'issued';
  elsif p_kind = 'fediverse' then
    if p_ttl_sec is null or p_ttl_sec not between 60 and 600 then raise exception 'invalid code' using errcode = '22023'; end if;
    select o.locked_until into v_lock from public.fediverse_email_otp o where o.pending_key = p_key for update;
    if v_lock is not null and v_lock > pg_catalog.now() then return 'locked'; end if;
    insert into public.fediverse_email_otp as o (pending_key, email, code_hash, attempts, locked_until, expires_at)
    values (p_key, p_payload, p_code_hash, 0, null, pg_catalog.now() + pg_catalog.make_interval(secs => p_ttl_sec))
    on conflict (pending_key) do update
      set email = excluded.email, code_hash = excluded.code_hash, attempts = 0, locked_until = null,
          expires_at = excluded.expires_at, created_at = pg_catalog.now();
    return 'issued';
  end if;
  raise exception 'unknown code kind' using errcode = '22023';
end $function$

CREATE OR REPLACE FUNCTION public.rout_stateless_otp_verify(p_kind text, p_key text, p_code text)
 RETURNS TABLE(outcome text, payload text, attempts_left integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  f public.fediverse_email_otp;
  l public.login_codes;
  v_hash text;
  v_attempts int;
begin
  if p_key is null or p_key !~ '^[0-9a-f]{64}$' then
    outcome := 'missing'; return next; return;
  end if;
  if p_code is null or p_code !~ '^[0-9]{6}$' then
    outcome := 'wrong'; return next; return;
  end if;
  if p_kind = 'login_code' then
    v_hash := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(p_key || ':' || p_code, 'UTF8')), 'hex');
    delete from public.login_codes c
     where c.email_hash = p_key and c.code_hash = v_hash and c.expires_at > pg_catalog.now() and c.attempts < 5
    returning * into l;
    if l.id is not null then
      outcome := 'ok'; payload := l.link; return next; return;
    end if;
    update public.login_codes c set attempts = c.attempts + 1
     where c.email_hash = p_key and c.expires_at > pg_catalog.now()
    returning c.attempts into v_attempts;
    if v_attempts is null then outcome := 'missing'; return next; return; end if;
    if v_attempts >= 5 then
      delete from public.login_codes c where c.email_hash = p_key;
      outcome := 'locked'; attempts_left := 0; return next; return;
    end if;
    outcome := 'wrong'; attempts_left := 5 - v_attempts; return next; return;
  elsif p_kind = 'fediverse' then
    select * into f from public.fediverse_email_otp o where o.pending_key = p_key for update;
    if not found then outcome := 'missing'; return next; return; end if;
    if f.locked_until is not null and f.locked_until > pg_catalog.now() then
      outcome := 'locked'; attempts_left := 0; return next; return;
    end if;
    if f.expires_at < pg_catalog.now() then outcome := 'expired'; return next; return; end if;
    v_hash := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(p_key || '|' || f.email || '|' || p_code, 'UTF8')), 'hex');
    if v_hash = f.code_hash then
      delete from public.fediverse_email_otp o where o.pending_key = p_key;
      outcome := 'ok'; payload := f.email; return next; return;
    end if;
    v_attempts := f.attempts + 1;
    update public.fediverse_email_otp o
       set attempts = v_attempts,
           locked_until = case when v_attempts >= 3 then pg_catalog.now() + interval '15 minutes' else null end
     where o.pending_key = p_key;
    outcome := case when v_attempts >= 3 then 'locked' else 'wrong' end;
    attempts_left := greatest(3 - v_attempts, 0);
    return next; return;
  end if;
  raise exception 'unknown code kind' using errcode = '22023';
end $function$

CREATE OR REPLACE FUNCTION public.rout_subscriber_join(p_handle text, p_hash text, p_ciphertext text, p_iv text, p_confirm_hash text, p_unsubscribe_hash text, p_locale text)
 RETURNS TABLE(outcome text, out_owner uuid, out_space text, out_list integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
#variable_conflict use_column
declare
  v_owner uuid;
  v_space text;
  v_blocks jsonb;
  v_has_block boolean;
  v_list integer;
  v_status text;
begin
  select p.id, 'root', p.blocks into v_owner, v_space, v_blocks
    from public.profiles p
   where lower(p.username) = lower(p_handle) and coalesce(p.status, 'active') = 'active'
   limit 1;
  if v_owner is null then
    select a.user_id, 'alias', a.blocks into v_owner, v_space, v_blocks
      from public.alias_profiles a where lower(a.handle) = lower(p_handle) limit 1;
  end if;
  if v_owner is null then
    return query select 'not_found'::text, null::uuid, null::text, null::integer;
    return;
  end if;

  select true, nullif(left(regexp_replace(coalesce(b->>'value', ''), '\D', '', 'g'), 9), '')::integer
    into v_has_block, v_list
    from jsonb_array_elements(case when jsonb_typeof(v_blocks) = 'array' then v_blocks else '[]'::jsonb end) b
   where b->>'kind' = 'newsletter' and coalesce(b->>'hidden', 'false') <> 'true'
   limit 1;
  if v_has_block is not true then
    return query select 'no_block'::text, null::uuid, null::text, null::integer;
    return;
  end if;

  select s.status into v_status from public.profile_subscribers s
   where s.owner_user_id = v_owner and s.space = v_space and s.email_hash = p_hash;
  if v_status = 'confirmed' then
    return query select 'already'::text, v_owner, v_space, v_list;
    return;
  end if;

  insert into public.profile_subscribers as s
    (owner_user_id, handle, space, email_hash, email_ciphertext, email_iv, status,
     confirm_token_hash, unsubscribe_token_hash, locale, brevo_list_id)
  values (v_owner, lower(p_handle), v_space, p_hash, p_ciphertext, p_iv, 'pending',
     p_confirm_hash, p_unsubscribe_hash, nullif(left(coalesce(p_locale, ''), 10), ''), v_list)
  on conflict (owner_user_id, space, email_hash) do update set
    handle = excluded.handle,
    email_ciphertext = excluded.email_ciphertext,
    email_iv = excluded.email_iv,
    status = 'pending',
    confirm_token_hash = excluded.confirm_token_hash,
    unsubscribe_token_hash = excluded.unsubscribe_token_hash,
    locale = excluded.locale,
    brevo_list_id = excluded.brevo_list_id,
    unsubscribed_at = null,
    updated_at = now();
  return query select 'pending'::text, v_owner, v_space, v_list;
end $function$

CREATE OR REPLACE FUNCTION public.rout_users_minor_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.is_minor := new.date_of_birth is not null and new.date_of_birth > (current_date - interval '16 years');
  if new.date_of_birth is not null and new.date_of_birth > (current_date - interval '18 years')
     and (tg_op = 'INSERT' or old.date_of_birth is distinct from new.date_of_birth) then
    new.qa_permission_level := 'verified_only';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.rout_vp_expire_own_open_stripe()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v uuid := public.rout_require_member(); n int;
begin
  update public.verification_payments set status = 'expired', updated_at = pg_catalog.now()
   where user_id = v and provider = 'stripe' and status in ('pending', 'incomplete');
  get diagnostics n = row_count;
  return n;
end $function$

CREATE OR REPLACE FUNCTION public.rout_vp_mark(p_id uuid, p_status text, p_provider_ref text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_status text;
begin
  if p_status not in ('processing', 'failed', 'expired', 'refunded', 'incomplete', 'pending', 'cancelled') then
    raise exception 'invalid payment status' using errcode = '22023';
  end if;
  select status into v_status from public.verification_payments where id = p_id for update;
  if not found then return 'not_found'; end if;
  if v_status = 'paid' and p_status <> 'refunded' then return 'paid'; end if;
  update public.verification_payments set status = p_status, provider_ref = coalesce(p_provider_ref, provider_ref),
         updated_at = pg_catalog.now()
   where id = p_id;
  return 'updated';
end $function$

CREATE OR REPLACE FUNCTION public.rout_vp_transfer_scan()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_open int; v_expired int;
begin
  update public.verification_payments set expires_at = created_at + interval '7 days'
   where expires_at is null and status in ('pending', 'awaiting_transfer');
  update public.verification_payments set last_scanned_at = pg_catalog.now()
   where status in ('pending', 'awaiting_transfer');
  get diagnostics v_open = row_count;
  update public.verification_payments set status = 'expired', updated_at = pg_catalog.now()
   where status in ('pending', 'awaiting_transfer') and expires_at is not null and expires_at < pg_catalog.now();
  get diagnostics v_expired = row_count;
  return pg_catalog.jsonb_build_object('scanned', v_open, 'expired', v_expired);
end $function$

CREATE OR REPLACE FUNCTION public.rout_webhook_delivery_enqueue(p_owner uuid, p_event_type text, p_payload jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare n int;
begin
  if p_owner is null or p_event_type is null or p_event_type !~ '^[a-z0-9_.:-]{1,80}$'
     or pg_catalog.octet_length(coalesce(p_payload, '{}'::jsonb)::text) > 65536 then
    raise exception 'invalid webhook delivery' using errcode = '22023';
  end if;
  insert into public.webhook_deliveries (endpoint_id, event_type, payload_json)
  select e.id, p_event_type, coalesce(p_payload, '{}'::jsonb) from public.webhook_endpoints e
   where e.owner_user_id = p_owner and e.active and (p_event_type = any (e.events) or pg_catalog.cardinality(e.events) = 0);
  get diagnostics n = row_count;
  return n;
end $function$

CREATE OR REPLACE FUNCTION public.rout_webhook_event_claim(p_id text, p_source text, p_kind text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v text;
begin
  if p_id is null or p_id !~ '^[A-Za-z0-9_:.-]{1,200}$' or p_source not in ('stripe')
     or coalesce(pg_catalog.length(p_kind), 0) > 120 then
    raise exception 'invalid webhook event' using errcode = '22023';
  end if;
  insert into public.webhook_events as w (id, source, kind, status, direction)
  values (p_id, p_source, p_kind, 'processing', 'inbound')
  on conflict (id) do update
     set status = 'processing', attempts = w.attempts + 1, error = null, updated_at = pg_catalog.now()
   where w.status = 'failed'
  returning w.id into v;
  return v is not null;
end $function$

CREATE OR REPLACE FUNCTION public.save_profile_draft(p_user_id uuid, p_space text, p_payload jsonb, p_expected_revision bigint)
 RETURNS TABLE(revision bigint, published_revision bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_current bigint;
begin
  if p_space not in ('verified', 'alias') then
    raise exception 'draft_space_invalid';
  end if;

  select d.revision into v_current
    from public.profile_drafts d
   where d.user_id = p_user_id and d.space = p_space
   for update;

  if v_current is null then
    if p_expected_revision <> 0 then raise exception 'draft_conflict'; end if;
    insert into public.profile_drafts (user_id, space, payload, revision)
    values (p_user_id, p_space, p_payload, 1);
  else
    if v_current <> p_expected_revision then raise exception 'draft_conflict'; end if;
    update public.profile_drafts d
       set payload = p_payload, revision = d.revision + 1, updated_at = now()
     where d.user_id = p_user_id and d.space = p_space;
  end if;

  return query
    select d.revision, d.published_revision
      from public.profile_drafts d
     where d.user_id = p_user_id and d.space = p_space;
end;
$function$

CREATE OR REPLACE FUNCTION public.security_audit_chain()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  prev text;
begin
  perform pg_advisory_xact_lock(727001);
  select current_hash into prev from public.security_audit_logs order by id desc limit 1;
  if prev is null then
    select last_hash into prev from public.security_audit_checkpoints order by day desc limit 1;
  end if;
  new.prev_hash := coalesce(prev, repeat('0', 64));
  new.created_at := date_trunc('milliseconds', coalesce(new.created_at, now()));
  new.current_hash := encode(sha256(convert_to(
    new.prev_hash || '|' || new.event_type || '|' || coalesce(new.user_id, '') || '|' ||
    coalesce(new.actor_id, '') || '|' || new.payload_json::text || '|' ||
    to_char(new.created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'UTF8')), 'hex');
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.security_audit_refuse()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' and tg_table_name = 'security_audit_logs' then
    if current_setting('rout.audit_retention',true) = 'on' and old.created_at < now() - interval '365 days' then return old; end if;
    if current_setting('rout.purge_user_id',true) = old.user_id and exists (
      select 1 from public.account_deletions d where d.user_id::text=old.user_id
      and d.cancelled_at is null and d.completed_at is null and d.purge_after<=now()
    ) then return old; end if;
  end if;
  raise exception 'security audit tables are append-only (% refused)', tg_op;
end $function$

CREATE OR REPLACE FUNCTION public.signin_guard_record(_identity_hash text, _success boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare r public.signin_throttle; new_failures int; lock_for interval;
begin
  if _identity_hash is null or length(_identity_hash) not between 16 and 128 then
    return jsonb_build_object('locked', false, 'retry_after', 0);
  end if;

  if _success then
    delete from public.signin_throttle where identity_hash = _identity_hash;
    return jsonb_build_object('locked', false, 'retry_after', 0);
  end if;

  select * into r from public.signin_throttle where identity_hash = _identity_hash for update;

  if r.identity_hash is null or r.window_started_at < now() - interval '15 minutes' then
    insert into public.signin_throttle (identity_hash, failures, window_started_at, locked_until)
    values (_identity_hash, 1, now(), null)
    on conflict (identity_hash) do update
      set failures = 1, window_started_at = now(), locked_until = null;
    return jsonb_build_object('locked', false, 'retry_after', 0);
  end if;

  new_failures := r.failures + 1;
  lock_for := case
    when new_failures >= 10 then interval '15 minutes'
    when new_failures >= 7 then interval '5 minutes'
    when new_failures >= 5 then interval '1 minute'
    else null end;

  update public.signin_throttle
     set failures = new_failures,
         locked_until = case when lock_for is null then null else now() + lock_for end
   where identity_hash = _identity_hash;

  delete from public.signin_throttle
   where window_started_at < now() - interval '1 day'
     and (locked_until is null or locked_until < now());

  if lock_for is null then
    return jsonb_build_object('locked', false, 'retry_after', 0);
  end if;
  return jsonb_build_object('locked', true,
    'retry_after', ceil(extract(epoch from lock_for))::int);
end;
$function$

CREATE OR REPLACE FUNCTION public.signin_guard_status(_identity_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare r public.signin_throttle;
begin
  select * into r from public.signin_throttle where identity_hash = _identity_hash;
  if r.identity_hash is null or r.locked_until is null or r.locked_until <= now() then
    return jsonb_build_object('locked', false, 'retry_after', 0);
  end if;
  return jsonb_build_object('locked', true,
    'retry_after', greatest(1, ceil(extract(epoch from (r.locked_until - now())))::int));
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_public_feedback(p_form uuid, p_rating integer, p_comment text, p_name text, p_consent boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare f public.feedback_forms; result uuid;
begin
  select * into f from public.feedback_forms where id=p_form;
  if not found or not public.feedback_form_is_public(f) then raise exception 'feedback_unavailable'; end if;
  if char_length(coalesce(p_comment,'')) > 2000 or char_length(coalesce(p_name,'')) > 100 then
    raise exception 'feedback_invalid';
  end if;
  if (f.type='text_review' and (p_rating is not null or char_length(trim(coalesce(p_comment,'')))=0))
    or (f.type<>'text_review' and (p_rating is null or
      p_rating < case when f.type='nps_10' then 0 else 1 end or
      p_rating > case when f.type='nps_10' then 10 when f.type='emoji_3' then 3 else 5 end)) then
    raise exception 'feedback_invalid';
  end if;
  insert into public.feedback_responses(form_id,rating,comment,reviewer_name,allow_featured)
    values(p_form,p_rating,nullif(trim(p_comment),''),nullif(trim(p_name),''),coalesce(p_consent,false)) returning id into result;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.sync_omni_semantic_draft()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare b jsonb; config jsonb; item jsonb; card uuid; path text; kept uuid[]:='{}';
begin
 for b in select value from jsonb_array_elements(coalesce(new.payload->'blocks','[]'::jsonb)) loop
  if b->>'kind'<>'social_grid' then continue; end if;
  begin config:=(b->>'value')::jsonb; exception when invalid_text_representation then continue; end;
  if jsonb_typeof(config->'items') is distinct from 'array' then continue; end if;
  for item in select value from jsonb_array_elements(config->'items') limit 30 loop
   path:=public.rout_grid_media_path(item->>'mediaUrl');
   if path is null or split_part(path,'/',1)<>new.user_id::text then continue; end if;
   select id into card from public.social_grid_items where user_id=new.user_id and profile_space=new.space
    and block_id=b->>'id' and source_item_id=item->>'id' limit 1;
   if card is null then continue; end if;
   insert into public.omni_matrix_items(id,user_id,profile_space,block_id,source_item_id,content_type,image_path,
    target_url,title,meta_tag,is_hero,kinetic_preview_path,created_at)
   values(card,new.user_id,new.space,b->>'id',item->>'id',
    (case when item->>'contentType' in ('article','podcast','program','short','event','social') then item->>'contentType' else 'social' end)::public.omni_content_type,
    path,nullif(item->>'targetUrl',''),left(coalesce(item->>'caption',''),150),left(nullif(item->>'metaTag',''),40),
    coalesce(item->'isHero'='true'::jsonb,false),
    case when public.rout_grid_media_path(item->>'kineticPreviewUrl') ~ '^[0-9a-f-]{36}/omni-[A-Za-z0-9._-]+\.webm$'
      and split_part(public.rout_grid_media_path(item->>'kineticPreviewUrl'),'/',1)=new.user_id::text
      then public.rout_grid_media_path(item->>'kineticPreviewUrl') else null end,
    coalesce(nullif(item->>'createdAt','')::timestamptz,now()))
   on conflict(id) do update set content_type=excluded.content_type,image_path=excluded.image_path,
    target_url=excluded.target_url,title=excluded.title,meta_tag=excluded.meta_tag,
    is_hero=excluded.is_hero,kinetic_preview_path=excluded.kinetic_preview_path;
   kept:=array_append(kept,card);
  end loop;
 end loop;
 delete from public.omni_matrix_items where user_id=new.user_id and profile_space=new.space and not(id=any(kept));
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.sync_social_grid_draft()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  b jsonb;
  config jsonb;
  item jsonb;
  ordinal bigint;
  kept uuid[] := '{}';
  card_id uuid;
begin
  for b in select value from jsonb_array_elements(coalesce(new.payload->'blocks','[]'::jsonb)) loop
    if b->>'kind' <> 'social_grid' then continue; end if;
    begin
      config := (b->>'value')::jsonb;
    exception when invalid_text_representation then
      continue;
    end;
    if jsonb_typeof(config->'items') <> 'array' then continue; end if;
    for item, ordinal in select value, ordinality from jsonb_array_elements(config->'items') with ordinality loop
      if ordinal > 30 or coalesce(item->>'id','') = '' or coalesce(item->>'mediaUrl','') = '' then continue; end if;
      insert into public.social_grid_items
        (user_id, profile_space, block_id, source_item_id, platform, media_url, caption, target_url, is_pinned, is_video, position, created_at)
      values (new.user_id, new.space, b->>'id', item->>'id',
        case when item->>'platform' in ('instagram','tiktok','article','custom') then item->>'platform' else 'custom' end,
        item->>'mediaUrl', coalesce(item->>'caption',''), nullif(item->>'targetUrl',''),
        coalesce(item->'pinned' = 'true'::jsonb,false), coalesce(item->'isVideo' = 'true'::jsonb,false),
        ordinal - 1, coalesce(nullif(item->>'createdAt','')::timestamptz, now()))
      on conflict (user_id, profile_space, block_id, source_item_id) do update set
        platform=excluded.platform, media_url=excluded.media_url, caption=excluded.caption,
        target_url=excluded.target_url, is_pinned=excluded.is_pinned, is_video=excluded.is_video,
        position=excluded.position
      returning id into card_id;
      kept := array_append(kept, card_id);
    end loop;
  end loop;
  delete from public.social_grid_items
    where user_id=new.user_id and profile_space=new.space and not (id = any(kept));
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.validate_ephemeral_presence()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare p jsonb := new.content_payload; q record;
begin
 if jsonb_typeof(p) is distinct from 'object' or octet_length(p::text)>4096 then raise exception 'invalid_status_payload'; end if;
 if new.status_type='micro_text' then
  if jsonb_typeof(p->'text') is distinct from 'string' or char_length(btrim(p->>'text')) not between 1 and 280
   or coalesce(p->>'theme','aurora') not in ('aurora','glass')
   or (p ? 'theme' and jsonb_typeof(p->'theme') is distinct from 'string')
   or coalesce(p->>'bg','none') not in ('none','sunset','ocean','forest','noir','candy','gold')
   or coalesce(p->>'font','classic') not in ('classic','display','mono','hand')
   or coalesce(p->>'align','center') not in ('left','center','right')
   or (p ? 'sticker' and (jsonb_typeof(p->'sticker') is distinct from 'string' or char_length(p->>'sticker') not between 1 and 8))
   or exists(select 1 from jsonb_object_keys(p) k where k not in ('text','theme','bg','font','align','sticker')) then raise exception 'invalid_micro_text'; end if;
 elsif new.status_type='omni_drop' then
  if jsonb_typeof(p->'blockId') is distinct from 'string' or char_length(p->>'blockId') not between 1 and 100
   or (p ? 'itemId' and (jsonb_typeof(p->'itemId') is distinct from 'string' or char_length(p->>'itemId') not between 1 and 100))
   or exists(select 1 from jsonb_object_keys(p) k where k not in ('blockId','itemId')) then raise exception 'invalid_omni_drop'; end if;
 else
  if jsonb_typeof(p->'questionId') is distinct from 'string' or exists(select 1 from jsonb_object_keys(p) k where k<>'questionId') then raise exception 'invalid_qa_reference'; end if;
  select owner_id,space,answered_at,story_until into q from public.profile_questions
   where id=(p->>'questionId')::uuid and owner_id=new.user_id and published and answer is not null and not is_quarantined;
  if not found or q.space<>new.space or q.story_until is null then raise exception 'invalid_qa_reference'; end if;
 end if;
 if tg_op='INSERT' then new.created_at:=now(); new.expires_at:=now()+interval '24 hours';
 else new.created_at:=old.created_at;new.expires_at:=old.expires_at;
  if new.user_id<>old.user_id or new.space<>old.space or new.status_type<>old.status_type then raise exception 'immutable_status_identity'; end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.wallet_credit(_user_id uuid, _amount_cents integer, _kind text DEFAULT 'topup'::text, _description text DEFAULT NULL::text, _reference text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  _balance integer;
begin
  if _amount_cents is null or _amount_cents <= 0 then
    raise exception 'wallet_credit: amount must be positive';
  end if;
  if _kind not in ('topup', 'refund', 'adjustment') then
    raise exception 'wallet_credit: invalid kind %', _kind;
  end if;

  insert into public.wallets (user_id) values (_user_id)
  on conflict (user_id) do nothing;

  -- Rijvergrendeling: parallelle webhooks wachten netjes op elkaar.
  select balance_cents into _balance
    from public.wallets where user_id = _user_id for update;

  begin
    insert into public.wallet_transactions
      (user_id, kind, amount_cents, description, reference)
    values (_user_id, _kind, _amount_cents, _description, _reference);
  exception when unique_violation then
    -- Zelfde Stripe-referentie: al geboekt, saldo ongewijzigd.
    return _balance;
  end;

  update public.wallets
     set balance_cents = balance_cents + _amount_cents
   where user_id = _user_id
   returning balance_cents into _balance;

  return _balance;
end $function$

CREATE OR REPLACE FUNCTION public.wallet_debit(_user_id uuid, _amount_cents integer, _description text DEFAULT NULL::text, _reference text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  _balance integer;
begin
  if _amount_cents is null or _amount_cents <= 0 then
    raise exception 'wallet_debit: amount must be positive';
  end if;

  insert into public.wallets (user_id) values (_user_id)
  on conflict (user_id) do nothing;

  select balance_cents into _balance
    from public.wallets where user_id = _user_id for update;

  if _balance is null or _balance < _amount_cents then
    return -1; -- onvoldoende saldo; niets geboekt
  end if;

  begin
    insert into public.wallet_transactions
      (user_id, kind, amount_cents, description, reference)
    values (_user_id, 'relay_fee', -_amount_cents, _description, _reference);
  exception when unique_violation then
    return _balance; -- deze periode al afgeschreven
  end;

  update public.wallets
     set balance_cents = balance_cents - _amount_cents
   where user_id = _user_id
   returning balance_cents into _balance;

  return _balance;
end $function$

CREATE OR REPLACE FUNCTION public.wt_assert(ok boolean, msg text)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
begin
  if not coalesce(ok, false) then
    raise exception '%', msg using errcode = 'P0001';
  end if;
  return true;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.activate_member_card(p_tap_ref text, p_activation_hash bytea)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_caller uuid := vault_enclave.caller_user_id();
  v_grant vault_enclave.sdm_tap_grants%rowtype;
  v_card vault_enclave.sdm_batch_cards%rowtype;
  v_code_ok boolean;
begin
  if v_caller is null then
    perform vault_enclave.append_audit(null, 'sdm_card_activate', 'denied', 'no_caller', null); return false;
  end if;
  if p_tap_ref is null or p_tap_ref !~ '^tap_[0-9a-f]{64}$'
     or (p_activation_hash is not null and octet_length(p_activation_hash) <> 32) then
    perform vault_enclave.append_audit(v_caller, 'sdm_card_activate', 'denied', 'bad_request', null); return false;
  end if;
  select * into v_grant from vault_enclave.sdm_tap_grants g
   where g.grant_digest = pg_catalog.sha256(pg_catalog.convert_to(p_tap_ref, 'UTF8')) for update;
  if not found or v_grant.consumed_at is not null or v_grant.expires_at < v_now then
    perform vault_enclave.append_audit(v_caller, 'sdm_card_activate', 'denied',
      case when not found then 'unknown_grant' when v_grant.consumed_at is not null then 'grant_spent' else 'grant_expired' end, null);
    return false;
  end if;
  -- The grant is spent whatever happens next: one tap, one answer.
  update vault_enclave.sdm_tap_grants set consumed_at = v_now, consumed_for = 'activation' where grant_digest = v_grant.grant_digest;
  select * into v_card from vault_enclave.sdm_batch_cards c where c.card_id = v_grant.card_id for update;
  -- Always run the full constant-time comparison, also when no code is required.
  v_code_ok := vault_enclave.ct_equal_32(p_activation_hash, v_card.activation_hash);
  if v_card.revoked_at is not null then
    perform vault_enclave.append_audit(v_caller, 'sdm_card_activate', 'denied', 'card_revoked', null); return false;
  end if;
  if v_card.owner_user_id is not null or v_card.activated_at is not null then
    perform vault_enclave.append_audit(v_caller, 'sdm_card_activate', 'denied', 'card_claimed', null); return false;
  end if;
  if v_card.activation_hash is not null and not v_code_ok then
    perform vault_enclave.append_audit(v_caller, 'sdm_card_activate', 'denied', 'activation_code_mismatch', null); return false;
  end if;
  update vault_enclave.sdm_batch_cards
     set owner_user_id = v_caller, activated_at = v_now, initial_counter = last_counter
   where card_id = v_card.card_id;
  perform vault_enclave.append_audit(v_caller, 'sdm_card_activate', 'granted', 'ok', null);
  return true;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.append_audit(p_actor uuid, p_action text, p_outcome text, p_reason text, p_ref text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_prev bytea;
  v_at timestamptz := pg_catalog.clock_timestamp();
begin
  -- One writer at a time keeps the chain linear (prev_hash is unique: no forks).
  perform pg_catalog.pg_advisory_xact_lock(7421003221);
  select a.entry_hash into v_prev from vault_enclave.audit_logs a order by a.seq desc limit 1;
  v_prev := coalesce(v_prev, pg_catalog.decode(pg_catalog.repeat('00', 32), 'hex'));
  insert into vault_enclave.audit_logs (occurred_at, actor_user_id, action, outcome, reason, token_ref, prev_hash, entry_hash)
  values (v_at, p_actor, p_action, p_outcome, p_reason, p_ref, v_prev,
          vault_enclave.audit_entry_hash(v_prev, v_at, p_actor, p_action, p_outcome, p_reason, p_ref));
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.begin_card_step_up(p_scope text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_caller uuid := vault_enclave.caller_user_id();
  v_ref text;
begin
  if v_caller is null then
    perform vault_enclave.append_audit(null, 'card_step_up_begin', 'denied', 'no_caller', null); return null;
  end if;
  if p_scope is null or p_scope not in ('*', 'card_reveal', 'card_lifecycle') then
    perform vault_enclave.append_audit(v_caller, 'card_step_up_begin', 'denied', 'bad_request', null); return null;
  end if;
  if not exists (select 1 from vault_enclave.sdm_batch_cards c
                  where c.owner_user_id = v_caller and c.activated_at is not null and c.revoked_at is null) then
    perform vault_enclave.append_audit(v_caller, 'card_step_up_begin', 'denied', 'no_card', null); return null;
  end if;
  update vault_enclave.card_step_up_intents set expires_at = v_now
   where user_id = v_caller and completed_at is null and expires_at > v_now;
  v_ref := 'csu_' || pg_catalog.encode(public.gen_random_bytes(32), 'hex');
  insert into vault_enclave.card_step_up_intents (intent_digest, user_id, scope, created_at, expires_at)
  values (pg_catalog.sha256(pg_catalog.convert_to(v_ref, 'UTF8')), v_caller, p_scope, v_now, v_now + interval '300 seconds');
  perform vault_enclave.append_audit(v_caller, 'card_step_up_begin', 'granted', p_scope, null);
  return v_ref;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.begin_sdm_tap(p_fleet_id uuid, p_uid_hash bytea, p_picc_data bytea, p_cmac bytea)
 RETURNS TABLE(granted boolean, attempt_id uuid, batch_id uuid, batch_owner uuid, encrypted_payload bytea, last_counter integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_card vault_enclave.sdm_batch_cards%rowtype;
  v_batch vault_enclave.sdm_batches%rowtype;
  v_failures int;
  v_attempt uuid;
  v_payload bytea;
begin
  if p_uid_hash is null or octet_length(p_uid_hash) <> 32
     or p_picc_data is null or octet_length(p_picc_data) <> 16 or p_cmac is null or octet_length(p_cmac) <> 8 then
    perform vault_enclave.append_audit(null, 'sdm_tap_begin', 'denied', 'malformed_tap', null);
    return query select false, null::uuid, null::uuid, null::uuid, null::bytea, null::integer; return;
  end if;
  select c.* into v_card from vault_enclave.sdm_batch_cards c
    join vault_enclave.sdm_batches b on b.batch_id = c.batch_id
   where c.uid_hash = p_uid_hash and b.fleet_id = p_fleet_id
   for update of c;
  if not found or v_card.revoked_at is not null then
    perform vault_enclave.append_audit(null, 'sdm_tap_begin', 'denied', case when found then 'card_revoked' else 'unknown_card' end, null);
    return query select false, null::uuid, null::uuid, null::uuid, null::bytea, null::integer; return;
  end if;
  select * into v_batch from vault_enclave.sdm_batches b where b.batch_id = v_card.batch_id;
  if v_batch.retired_at is not null then
    perform vault_enclave.append_audit(null, 'sdm_tap_begin', 'denied', 'batch_retired', v_batch.sdm_ref);
    return query select false, null::uuid, null::uuid, null::uuid, null::bytea, null::integer; return;
  end if;
  -- Serialise taps of one card so parallel requests cannot all pass the lockout.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_card.card_id::text, 7421003245));
  delete from vault_enclave.sdm_tap_attempts a where a.card_id = v_card.card_id and a.started_at < v_now - interval '1 day';
  delete from vault_enclave.sdm_tap_grants g where g.card_id = v_card.card_id and g.expires_at < v_now - interval '1 day';
  select count(*)::int into v_failures from vault_enclave.sdm_tap_attempts a
   where a.card_id = v_card.card_id and a.outcome <> 'verified' and a.started_at > v_now - interval '10 minutes';
  if v_failures >= 5 then
    perform vault_enclave.append_audit(v_card.owner_user_id, 'sdm_tap_begin', 'denied', 'card_locked', v_batch.sdm_ref);
    return query select false, null::uuid, null::uuid, null::uuid, null::bytea, null::integer; return;
  end if;
  select t.encrypted_payload into v_payload from vault_enclave.opaque_tokens t
   where t.token_ref = v_batch.sdm_ref and t.owner_user_id = v_batch.owner_user_id and t.token_type = 'sdm';
  if not found then
    perform vault_enclave.append_audit(v_card.owner_user_id, 'sdm_tap_begin', 'denied', 'envelope_missing', v_batch.sdm_ref);
    return query select false, null::uuid, null::uuid, null::uuid, null::bytea, null::integer; return;
  end if;
  insert into vault_enclave.sdm_tap_attempts (card_id, tap_digest, started_at)
  values (v_card.card_id, pg_catalog.sha256(p_picc_data || p_cmac), v_now)
  returning sdm_tap_attempts.attempt_id into v_attempt;
  perform vault_enclave.append_audit(v_card.owner_user_id, 'sdm_tap_begin', 'granted', 'pending', v_batch.sdm_ref);
  return query select true, v_attempt, v_batch.batch_id, v_batch.owner_user_id, v_payload, v_card.last_counter;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.claim_card_step_up(p_intent_ref text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_caller uuid := vault_enclave.caller_user_id();
  v_intent vault_enclave.card_step_up_intents%rowtype;
begin
  if v_caller is null or p_intent_ref is null or p_intent_ref !~ '^csu_[0-9a-f]{64}$' then
    perform vault_enclave.append_audit(v_caller, 'card_step_up_claim', 'denied', 'bad_request', null); return null;
  end if;
  select * into v_intent from vault_enclave.card_step_up_intents i
   where i.intent_digest = pg_catalog.sha256(pg_catalog.convert_to(p_intent_ref, 'UTF8')) for update;
  if not found or v_intent.user_id is distinct from v_caller then
    perform vault_enclave.append_audit(v_caller, 'card_step_up_claim', 'denied', 'unknown_intent', null); return null;
  end if;
  if v_intent.claimed_at is not null then
    perform vault_enclave.append_audit(v_caller, 'card_step_up_claim', 'denied', 'intent_spent', null); return null;
  end if;
  if v_intent.expires_at <= v_now then
    perform vault_enclave.append_audit(v_caller, 'card_step_up_claim', 'denied', 'intent_expired', null); return null;
  end if;
  if v_intent.completed_at is null then return null; end if;
  update vault_enclave.card_step_up_intents set claimed_at = v_now where intent_digest = v_intent.intent_digest;
  perform vault_enclave.append_audit(v_caller, 'card_step_up_claim', 'granted', v_intent.scope, null);
  return v_intent.scope;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.complete_card_step_up(p_tap_ref text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_caller uuid := vault_enclave.caller_user_id();
  v_intent vault_enclave.card_step_up_intents%rowtype;
  v_ok boolean;
begin
  if v_caller is null then
    perform vault_enclave.append_audit(null, 'card_step_up_complete', 'denied', 'no_caller', null); return false;
  end if;
  select * into v_intent from vault_enclave.card_step_up_intents i
   where i.user_id = v_caller and i.completed_at is null and i.expires_at > v_now
   order by i.created_at desc limit 1 for update;
  if not found then
    perform vault_enclave.append_audit(v_caller, 'card_step_up_complete', 'denied', 'no_intent', null); return false;
  end if;
  select c.granted into v_ok from vault_enclave.consume_sdm_tap(p_tap_ref, 'step_up') c;
  if v_ok is not true then
    perform vault_enclave.append_audit(v_caller, 'card_step_up_complete', 'denied', 'tap_refused', null); return false;
  end if;
  update vault_enclave.card_step_up_intents set completed_at = v_now where intent_digest = v_intent.intent_digest;
  perform vault_enclave.append_audit(v_caller, 'card_step_up_complete', 'granted', v_intent.scope, null);
  return true;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.confirm_sdm_recovery(p_attempt_id uuid, p_picc_data bytea, p_cmac bytea, p_verified boolean, p_read_counter integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_attempt vault_enclave.sdm_recovery_attempts%rowtype;
  v_ref text;
  v_rows int;
begin
  select * into v_attempt from vault_enclave.sdm_recovery_attempts a where a.attempt_id = p_attempt_id for update;
  if not found or v_attempt.outcome <> 'pending' then
    perform vault_enclave.append_audit(null, 'sdm_recovery_confirm', 'denied', 'attempt_not_pending', null);
    return false;
  end if;
  select c.sdm_ref into v_ref from vault_enclave.sdm_cards c where c.card_id = v_attempt.card_id;
  if p_verified is distinct from true
     or v_now - v_attempt.started_at > interval '60 seconds'
     or p_picc_data is null or p_cmac is null
     or pg_catalog.sha256(p_picc_data || p_cmac) <> v_attempt.tap_digest
     or p_read_counter is null or p_read_counter not between 0 and 16777214 then
    update vault_enclave.sdm_recovery_attempts set outcome = 'failed', closed_at = v_now where attempt_id = v_attempt.attempt_id;
    perform vault_enclave.append_audit(v_attempt.owner_user_id, 'sdm_recovery_confirm', 'denied',
      case when p_verified is distinct from true then 'cmac_invalid'
           when v_now - v_attempt.started_at > interval '60 seconds' then 'attempt_expired'
           when p_read_counter is null or p_read_counter not between 0 and 16777214 then 'bad_counter'
           else 'tap_mismatch' end, v_ref);
    return false;
  end if;
  -- Strictly increasing counter, atomically: the same tap URL never works twice.
  update vault_enclave.sdm_cards c set last_counter = p_read_counter
   where c.card_id = v_attempt.card_id and c.revoked_at is null
     and (c.last_counter is null or c.last_counter < p_read_counter);
  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    update vault_enclave.sdm_recovery_attempts set outcome = 'failed', closed_at = v_now where attempt_id = v_attempt.attempt_id;
    perform vault_enclave.append_audit(v_attempt.owner_user_id, 'sdm_recovery_confirm', 'denied', 'replayed', v_ref);
    return false;
  end if;
  update vault_enclave.sdm_recovery_attempts
     set outcome = 'verified', closed_at = v_now, read_counter = p_read_counter
   where attempt_id = v_attempt.attempt_id;
  perform vault_enclave.append_audit(v_attempt.owner_user_id, 'sdm_recovery_confirm', 'granted', 'ok', v_ref);
  return true;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.confirm_sdm_tap(p_attempt_id uuid, p_picc_data bytea, p_cmac bytea, p_verified boolean, p_read_counter integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_attempt vault_enclave.sdm_tap_attempts%rowtype;
  v_owner uuid;
  v_rows int;
  v_grant text;
begin
  select * into v_attempt from vault_enclave.sdm_tap_attempts a where a.attempt_id = p_attempt_id for update;
  if not found or v_attempt.outcome <> 'pending' then
    perform vault_enclave.append_audit(null, 'sdm_tap_confirm', 'denied', 'attempt_not_pending', null);
    return null;
  end if;
  select c.owner_user_id into v_owner from vault_enclave.sdm_batch_cards c where c.card_id = v_attempt.card_id;
  if p_verified is distinct from true
     or v_now - v_attempt.started_at > interval '60 seconds'
     or p_picc_data is null or p_cmac is null
     or pg_catalog.sha256(p_picc_data || p_cmac) <> v_attempt.tap_digest
     or p_read_counter is null or p_read_counter not between 0 and 16777214 then
    update vault_enclave.sdm_tap_attempts set outcome = 'failed', closed_at = v_now where attempt_id = v_attempt.attempt_id;
    perform vault_enclave.append_audit(v_owner, 'sdm_tap_confirm', 'denied',
      case when p_verified is distinct from true then 'cmac_invalid'
           when v_now - v_attempt.started_at > interval '60 seconds' then 'attempt_expired'
           when p_read_counter is null or p_read_counter not between 0 and 16777214 then 'bad_counter'
           else 'tap_mismatch' end, null);
    return null;
  end if;
  update vault_enclave.sdm_batch_cards c set last_counter = p_read_counter
   where c.card_id = v_attempt.card_id and c.revoked_at is null
     and (c.last_counter is null or c.last_counter < p_read_counter);
  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    update vault_enclave.sdm_tap_attempts set outcome = 'failed', closed_at = v_now where attempt_id = v_attempt.attempt_id;
    perform vault_enclave.append_audit(v_owner, 'sdm_tap_confirm', 'denied', 'replayed', null);
    return null;
  end if;
  update vault_enclave.sdm_tap_attempts set outcome = 'verified', closed_at = v_now, read_counter = p_read_counter
   where attempt_id = v_attempt.attempt_id;
  v_grant := 'tap_' || pg_catalog.encode(public.gen_random_bytes(32), 'hex');
  insert into vault_enclave.sdm_tap_grants (grant_digest, card_id, created_at, expires_at)
  values (pg_catalog.sha256(pg_catalog.convert_to(v_grant, 'UTF8')), v_attempt.card_id, v_now, v_now + interval '120 seconds');
  perform vault_enclave.append_audit(v_owner, 'sdm_tap_confirm', 'granted', 'ok', null);
  return v_grant;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.consume_sdm_tap(p_tap_ref text, p_purpose text)
 RETURNS TABLE(granted boolean, card_state text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_caller uuid := vault_enclave.caller_user_id();
  v_grant vault_enclave.sdm_tap_grants%rowtype;
  v_card vault_enclave.sdm_batch_cards%rowtype;
begin
  if p_tap_ref is null or p_tap_ref !~ '^tap_[0-9a-f]{64}$' or p_purpose not in ('public_proof', 'step_up') then
    perform vault_enclave.append_audit(v_caller, 'sdm_tap_consume', 'denied', 'bad_request', null);
    return query select false, null::text; return;
  end if;
  select * into v_grant from vault_enclave.sdm_tap_grants g
   where g.grant_digest = pg_catalog.sha256(pg_catalog.convert_to(p_tap_ref, 'UTF8')) for update;
  if not found or v_grant.consumed_at is not null or v_grant.expires_at < v_now then
    perform vault_enclave.append_audit(v_caller, 'sdm_tap_consume', 'denied',
      case when not found then 'unknown_grant' when v_grant.consumed_at is not null then 'grant_spent' else 'grant_expired' end, null);
    return query select false, null::text; return;
  end if;
  select * into v_card from vault_enclave.sdm_batch_cards c where c.card_id = v_grant.card_id;
  if v_card.revoked_at is not null or (p_purpose = 'step_up' and (v_caller is null or v_card.owner_user_id is distinct from v_caller)) then
    update vault_enclave.sdm_tap_grants set consumed_at = v_now, consumed_for = p_purpose where grant_digest = v_grant.grant_digest;
    perform vault_enclave.append_audit(v_caller, 'sdm_tap_consume', 'denied',
      case when v_card.revoked_at is not null then 'card_revoked' else 'not_card_owner' end, null);
    return query select false, null::text; return;
  end if;
  update vault_enclave.sdm_tap_grants set consumed_at = v_now, consumed_for = p_purpose where grant_digest = v_grant.grant_digest;
  perform vault_enclave.append_audit(v_caller, 'sdm_tap_consume', 'granted', p_purpose, null);
  return query select true, case when v_card.owner_user_id is null then 'unactivated' else 'active' end;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.ct_equal_32(p_a bytea, p_b bytea)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_zero constant bytea := pg_catalog.decode(pg_catalog.repeat('00', 32), 'hex');
  v_bad integer := 0;
  v_a bytea := p_a;
  v_b bytea := p_b;
  v_diff integer := 0;
begin
  -- Wrong length or null still walks all 32 bytes, against a zero buffer.
  if v_a is null or pg_catalog.octet_length(v_a) <> 32 then v_a := v_zero; v_bad := 1; end if;
  if v_b is null or pg_catalog.octet_length(v_b) <> 32 then v_b := v_zero; v_bad := 1; end if;
  for i in 0..31 loop
    v_diff := v_diff | (pg_catalog.get_byte(v_a, i) # pg_catalog.get_byte(v_b, i));
  end loop;
  return (v_diff | v_bad) = 0;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.mark_sdm_batch_exported(p_batch_id uuid, p_station_id uuid)
 RETURNS TABLE(granted boolean, station_public_key bytea, batch_owner uuid, batch_payload bytea, fleet_owner uuid, fleet_payload bytea)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_caller uuid := vault_enclave.caller_user_id();
  v_batch vault_enclave.sdm_batches%rowtype;
  v_fleet vault_enclave.sdm_fleet_keys%rowtype;
  v_station vault_enclave.sdm_stations%rowtype;
  v_batch_payload bytea;
  v_fleet_payload bytea;
begin
  if v_caller is null or not public.rout_is_admin_member(v_caller) then
    perform vault_enclave.append_audit(v_caller, 'sdm_batch_export', 'denied', 'not_admin', null);
    return query select false, null::bytea, null::uuid, null::bytea, null::uuid, null::bytea; return;
  end if;
  select * into v_station from vault_enclave.sdm_stations s where s.station_id = p_station_id for share;
  if not found or v_station.retired_at is not null then
    perform vault_enclave.append_audit(v_caller, 'sdm_batch_export', 'denied', 'unknown_station', null);
    return query select false, null::bytea, null::uuid, null::bytea, null::uuid, null::bytea; return;
  end if;
  select * into v_batch from vault_enclave.sdm_batches b where b.batch_id = p_batch_id for update;
  if not found or v_batch.retired_at is not null then
    perform vault_enclave.append_audit(v_caller, 'sdm_batch_export', 'denied', 'unknown_batch', null);
    return query select false, null::bytea, null::uuid, null::bytea, null::uuid, null::bytea; return;
  end if;
  select * into v_fleet from vault_enclave.sdm_fleet_keys f where f.fleet_id = v_batch.fleet_id;
  select t.encrypted_payload into v_batch_payload from vault_enclave.opaque_tokens t
   where t.token_ref = v_batch.sdm_ref and t.owner_user_id = v_batch.owner_user_id and t.token_type = 'sdm';
  select t.encrypted_payload into v_fleet_payload from vault_enclave.opaque_tokens t
   where t.token_ref = v_fleet.sdm_ref and t.owner_user_id = v_fleet.owner_user_id and t.token_type = 'sdm';
  if v_fleet.fleet_id is null or v_fleet.retired_at is not null or v_batch_payload is null or v_fleet_payload is null then
    perform vault_enclave.append_audit(v_caller, 'sdm_batch_export', 'denied', 'keys_unavailable', v_batch.sdm_ref);
    return query select false, null::bytea, null::uuid, null::bytea, null::uuid, null::bytea; return;
  end if;
  update vault_enclave.sdm_batches set exported_at = coalesce(exported_at, pg_catalog.clock_timestamp())
   where batch_id = v_batch.batch_id;
  perform vault_enclave.append_audit(v_caller, 'sdm_batch_export', 'granted',
    'fp_' || pg_catalog.encode(v_station.fingerprint, 'hex'), v_batch.sdm_ref);
  return query select true, v_station.public_key, v_batch.owner_user_id, v_batch_payload, v_fleet.owner_user_id, v_fleet_payload;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.register_sdm_batch(p_fleet_id uuid, p_sdm_ref text, p_label text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_caller uuid := vault_enclave.caller_user_id();
  v_ref text := case when p_sdm_ref ~ '^sdm_[0-9a-f]{64}$' then p_sdm_ref end;
  v_label text := pg_catalog.btrim(coalesce(p_label, ''));
  v_id uuid;
begin
  if v_caller is null or not public.rout_is_admin_member(v_caller) then
    perform vault_enclave.append_audit(v_caller, 'sdm_batch_register', 'denied', 'not_admin', v_ref); return null;
  end if;
  if not exists (select 1 from vault_enclave.sdm_fleet_keys f where f.fleet_id = p_fleet_id and f.retired_at is null)
     or char_length(v_label) not between 1 and 80
     or v_ref is null or not exists (
       select 1 from vault_enclave.opaque_tokens t where t.token_ref = v_ref and t.owner_user_id = v_caller and t.token_type = 'sdm')
     or not vault_enclave.sdm_ref_free(v_ref) then
    perform vault_enclave.append_audit(v_caller, 'sdm_batch_register', 'denied', 'bad_request', v_ref); return null;
  end if;
  insert into vault_enclave.sdm_batches (fleet_id, owner_user_id, sdm_ref, label)
  values (p_fleet_id, v_caller, v_ref, v_label) returning batch_id into v_id;
  perform vault_enclave.append_audit(v_caller, 'sdm_batch_register', 'granted', 'ok', v_ref);
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.register_sdm_batch_cards(p_batch_id uuid, p_uid_hashes bytea[], p_activation_hashes bytea[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_caller uuid := vault_enclave.caller_user_id();
  v_batch vault_enclave.sdm_batches%rowtype;
  v_n int := coalesce(pg_catalog.array_length(p_uid_hashes, 1), 0);
  v_rows int;
begin
  select * into v_batch from vault_enclave.sdm_batches b where b.batch_id = p_batch_id for update;
  if v_caller is null or not public.rout_is_admin_member(v_caller) or not found
     or v_batch.owner_user_id <> v_caller or v_batch.retired_at is not null then
    perform vault_enclave.append_audit(v_caller, 'sdm_batch_cards_register', 'denied', 'not_batch_owner', v_batch.sdm_ref); return null;
  end if;
  if v_n not between 1 and 5000
     or (p_activation_hashes is not null and coalesce(pg_catalog.array_length(p_activation_hashes, 1), 0) <> v_n)
     or exists (select 1 from pg_catalog.unnest(p_uid_hashes) h where h is null or octet_length(h) <> 32)
     or exists (select 1 from pg_catalog.unnest(p_activation_hashes) h where h is not null and octet_length(h) <> 32) then
    perform vault_enclave.append_audit(v_caller, 'sdm_batch_cards_register', 'denied', 'bad_manifest', v_batch.sdm_ref); return null;
  end if;
  insert into vault_enclave.sdm_batch_cards (batch_id, uid_hash, activation_hash)
  select v_batch.batch_id, u.h, a.h
    from pg_catalog.unnest(p_uid_hashes) with ordinality u(h, i)
    left join pg_catalog.unnest(p_activation_hashes) with ordinality a(h, i) on a.i = u.i
  on conflict (uid_hash) do nothing;
  get diagnostics v_rows = row_count;
  perform vault_enclave.append_audit(v_caller, 'sdm_batch_cards_register', 'granted', 'imported_' || v_rows, v_batch.sdm_ref);
  return v_rows;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.register_sdm_card(p_sdm_ref text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_caller uuid := vault_enclave.caller_user_id();
  v_ref text := case when p_sdm_ref ~ '^sdm_[0-9a-f]{64}$' then p_sdm_ref end;
  v_card uuid;
begin
  if v_caller is null then
    perform vault_enclave.append_audit(null, 'sdm_card_register', 'denied', 'no_caller', v_ref); return null;
  end if;
  if v_ref is null or not exists (
       select 1 from vault_enclave.opaque_tokens t where t.token_ref = v_ref and t.owner_user_id = v_caller and t.token_type = 'sdm') then
    perform vault_enclave.append_audit(v_caller, 'sdm_card_register', 'denied', 'not_owned_sdm', v_ref); return null;
  end if;
  if exists (select 1 from vault_enclave.sdm_cards c where c.sdm_ref = v_ref) then
    perform vault_enclave.append_audit(v_caller, 'sdm_card_register', 'denied', 'already_linked', v_ref); return null;
  end if;
  insert into vault_enclave.sdm_cards (owner_user_id, sdm_ref) values (v_caller, v_ref) returning card_id into v_card;
  perform vault_enclave.append_audit(v_caller, 'sdm_card_register', 'granted', 'ok', v_ref);
  return v_card;
end $function$

