CREATE OR REPLACE FUNCTION vault_enclave.register_sdm_station(p_label text, p_public_key bytea)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_caller uuid := vault_enclave.caller_user_id();
  v_label text := pg_catalog.btrim(coalesce(p_label, ''));
  v_id uuid;
begin
  if v_caller is null or not public.rout_is_admin_member(v_caller) then
    perform vault_enclave.append_audit(v_caller, 'sdm_station_register', 'denied', 'not_admin', null); return null;
  end if;
  if char_length(v_label) not between 1 and 80 or p_public_key is null
     or octet_length(p_public_key) <> 65 or pg_catalog.get_byte(p_public_key, 0) <> 4 then
    perform vault_enclave.append_audit(v_caller, 'sdm_station_register', 'denied', 'bad_request', null); return null;
  end if;
  if exists (select 1 from vault_enclave.sdm_stations s where s.public_key = p_public_key) then
    perform vault_enclave.append_audit(v_caller, 'sdm_station_register', 'denied', 'duplicate_key', null); return null;
  end if;
  insert into vault_enclave.sdm_stations (label, public_key, fingerprint, registered_by)
  values (v_label, p_public_key, pg_catalog.sha256(p_public_key), v_caller) returning station_id into v_id;
  perform vault_enclave.append_audit(v_caller, 'sdm_station_register', 'granted',
    'fp_' || pg_catalog.encode(pg_catalog.sha256(p_public_key), 'hex'), null);
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.register_server_key(p_kid bytea, p_public_key bytea, p_wrapped_seed bytea, p_kek_id bytea)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_caller uuid := vault_enclave.caller_user_id();
  v_rows int;
begin
  if v_caller is null then
    perform vault_enclave.append_audit(null, 'server_key_register', 'denied', 'no_caller', null); return false;
  end if;
  begin
    insert into vault_enclave.server_keys (kid, public_key, wrapped_seed, kek_id)
    values (p_kid, p_public_key, p_wrapped_seed, p_kek_id)
    on conflict do nothing;
    get diagnostics v_rows = row_count;
  exception when check_violation or not_null_violation then
    perform vault_enclave.append_audit(v_caller, 'server_key_register', 'denied', 'malformed', null); return false;
  end;
  if v_rows = 0 then
    perform vault_enclave.append_audit(v_caller, 'server_key_register', 'denied', 'active_key_exists', null); return false;
  end if;
  perform vault_enclave.append_audit(v_caller, 'server_key_register', 'granted', 'ok', null);
  return true;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.register_step_up_proof(p_proof_id uuid, p_method text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_caller uuid := vault_enclave.caller_user_id();
begin
  if v_caller is null then
    perform vault_enclave.append_audit(null, 'step_up_register', 'denied', 'no_caller', null); return false;
  end if;
  if p_method is distinct from 'passkey' then
    perform vault_enclave.append_audit(v_caller, 'step_up_register', 'denied', 'method_not_passkey', null); return false;
  end if;
  if p_proof_id is null or exists (select 1 from vault_enclave.step_up_proofs s where s.proof_id = p_proof_id) then
    perform vault_enclave.append_audit(v_caller, 'step_up_register', 'denied', 'proof_reused', null); return false;
  end if;
  -- Spent and stale proofs are useless after 300 s; keep the table small.
  delete from vault_enclave.step_up_proofs s where s.verified_at < pg_catalog.clock_timestamp() - interval '1 hour';
  insert into vault_enclave.step_up_proofs (proof_id, user_id, method, verified_at)
  values (p_proof_id, v_caller, 'passkey', pg_catalog.clock_timestamp());
  perform vault_enclave.append_audit(v_caller, 'step_up_register', 'granted', 'ok', null);
  return true;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.retire_sdm_station(p_station_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_caller uuid := vault_enclave.caller_user_id();
  v_rows int;
begin
  if v_caller is null or not public.rout_is_admin_member(v_caller) then
    perform vault_enclave.append_audit(v_caller, 'sdm_station_retire', 'denied', 'not_admin', null); return false;
  end if;
  update vault_enclave.sdm_stations set retired_at = pg_catalog.clock_timestamp()
   where station_id = p_station_id and retired_at is null;
  get diagnostics v_rows = row_count;
  perform vault_enclave.append_audit(v_caller, 'sdm_station_retire', case when v_rows = 1 then 'granted' else 'denied' end,
    case when v_rows = 1 then 'ok' else 'unknown_station' end, null);
  return v_rows = 1;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.retrieve_opaque_token(p_token_ref text, p_step_up_verified boolean, p_step_up_proof_id uuid)
 RETURNS TABLE(granted boolean, token_type text, encrypted_payload bytea)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_caller uuid := vault_enclave.caller_user_id();
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_proof vault_enclave.step_up_proofs%rowtype;
  v_token vault_enclave.opaque_tokens%rowtype;
  v_ref text := case when p_token_ref ~ '^(vtk|vcc|mpc|sdm)_[0-9a-f]{64}$' then p_token_ref end;
begin
  if v_caller is null then
    perform vault_enclave.append_audit(null, 'token_retrieve', 'denied', 'no_caller', v_ref);
    return query select false, null::text, null::bytea; return;
  end if;
  if v_ref is null then
    perform vault_enclave.append_audit(v_caller, 'token_retrieve', 'denied', 'malformed_ref', null);
    return query select false, null::text, null::bytea; return;
  end if;
  if p_step_up_verified is distinct from true then
    perform vault_enclave.append_audit(v_caller, 'token_retrieve', 'denied', 'step_up_missing', v_ref);
    return query select false, null::text, null::bytea; return;
  end if;
  select * into v_proof from vault_enclave.step_up_proofs s
   where s.proof_id = p_step_up_proof_id and s.user_id = v_caller for update;
  if not found then
    perform vault_enclave.append_audit(v_caller, 'token_retrieve', 'denied', 'proof_unknown', v_ref);
    return query select false, null::text, null::bytea; return;
  end if;
  if v_proof.consumed_at is not null then
    perform vault_enclave.append_audit(v_caller, 'token_retrieve', 'denied', 'proof_replayed', v_ref);
    return query select false, null::text, null::bytea; return;
  end if;
  if v_proof.method <> 'passkey' or v_now - v_proof.verified_at > interval '300 seconds'
     or v_proof.verified_at > v_now + interval '5 seconds' then
    perform vault_enclave.append_audit(v_caller, 'token_retrieve', 'denied', 'proof_expired', v_ref);
    return query select false, null::text, null::bytea; return;
  end if;
  -- Spend the proof before the lookup, so a valid proof can't probe many refs.
  update vault_enclave.step_up_proofs set consumed_at = v_now where proof_id = v_proof.proof_id;
  select * into v_token from vault_enclave.opaque_tokens t
   where t.token_ref = v_ref and t.owner_user_id = v_caller;
  if not found then
    perform vault_enclave.append_audit(v_caller, 'token_retrieve', 'denied', 'not_found', v_ref);
    return query select false, null::text, null::bytea; return;
  end if;
  perform vault_enclave.append_audit(v_caller, 'token_retrieve', 'granted', 'ok', v_ref);
  return query select true, v_token.token_type, v_token.encrypted_payload;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.retrieve_sdm_for_recovery(p_card_id uuid, p_picc_data bytea, p_cmac bytea)
 RETURNS TABLE(granted boolean, attempt_id uuid, owner_user_id uuid, sdm_ref text, encrypted_payload bytea, last_counter integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_card vault_enclave.sdm_cards%rowtype;
  v_fail record;
  v_attempt uuid;
  v_payload bytea;
begin
  select * into v_card from vault_enclave.sdm_cards c where c.card_id = p_card_id for update;
  if not found or v_card.revoked_at is not null then
    perform vault_enclave.append_audit(null, 'sdm_recovery_retrieve', 'denied', case when found then 'card_revoked' else 'unknown_card' end, v_card.sdm_ref);
    return query select false, null::uuid, null::uuid, null::text, null::bytea, null::integer; return;
  end if;
  -- Serialise all of this member's recovery attempts, so parallel taps cannot
  -- all pass the lockout check before any of them is counted.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_card.owner_user_id::text, 7421003224));
  -- Closed attempts older than a day no longer affect the lockout; the audit chain keeps the history.
  delete from vault_enclave.sdm_recovery_attempts a where a.owner_user_id = v_card.owner_user_id and a.started_at < v_now - interval '1 day';
  select * into v_fail from vault_enclave.sdm_failures(v_card.card_id, v_card.owner_user_id, v_now);
  if v_fail.card_failures >= 3 or v_fail.owner_failures >= 3 then
    perform vault_enclave.append_audit(v_card.owner_user_id, 'sdm_recovery_retrieve', 'denied',
      case when v_fail.card_failures >= 3 then 'card_locked' else 'account_locked' end, v_card.sdm_ref);
    return query select false, null::uuid, null::uuid, null::text, null::bytea, null::integer; return;
  end if;
  if p_picc_data is null or p_cmac is null or octet_length(p_picc_data) <> 16 or octet_length(p_cmac) <> 8 then
    insert into vault_enclave.sdm_recovery_attempts (card_id, owner_user_id, tap_digest, started_at, outcome, closed_at)
    values (v_card.card_id, v_card.owner_user_id, pg_catalog.sha256(coalesce(p_picc_data, ''::bytea) || coalesce(p_cmac, ''::bytea)), v_now, 'failed', v_now);
    perform vault_enclave.append_audit(v_card.owner_user_id, 'sdm_recovery_retrieve', 'denied', 'malformed_tap', v_card.sdm_ref);
    return query select false, null::uuid, null::uuid, null::text, null::bytea, null::integer; return;
  end if;
  select t.encrypted_payload into v_payload from vault_enclave.opaque_tokens t
   where t.token_ref = v_card.sdm_ref and t.owner_user_id = v_card.owner_user_id and t.token_type = 'sdm';
  if not found then
    perform vault_enclave.append_audit(v_card.owner_user_id, 'sdm_recovery_retrieve', 'denied', 'envelope_missing', v_card.sdm_ref);
    return query select false, null::uuid, null::uuid, null::text, null::bytea, null::integer; return;
  end if;
  insert into vault_enclave.sdm_recovery_attempts (card_id, owner_user_id, tap_digest, started_at)
  values (v_card.card_id, v_card.owner_user_id, pg_catalog.sha256(p_picc_data || p_cmac), v_now)
  returning sdm_recovery_attempts.attempt_id into v_attempt;
  perform vault_enclave.append_audit(v_card.owner_user_id, 'sdm_recovery_retrieve', 'granted', 'pending', v_card.sdm_ref);
  return query select true, v_attempt, v_card.owner_user_id, v_card.sdm_ref, v_payload, v_card.last_counter;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.revoke_member_cards()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_caller uuid := vault_enclave.caller_user_id();
  v_n integer;
begin
  if v_caller is null then
    perform vault_enclave.append_audit(null, 'sdm_card_revoke', 'denied', 'no_caller', null); return 0;
  end if;
  update vault_enclave.sdm_batch_cards set revoked_at = v_now
   where owner_user_id = v_caller and revoked_at is null;
  get diagnostics v_n = row_count;
  update vault_enclave.card_step_up_intents set expires_at = v_now
   where user_id = v_caller and claimed_at is null and expires_at > v_now;
  perform vault_enclave.append_audit(v_caller, 'sdm_card_revoke', 'granted', 'cards:' || v_n::text, null);
  return v_n;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.store_opaque_token(p_token_type text, p_encrypted_payload bytea)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_caller uuid := vault_enclave.caller_user_id();
  v_ref text;
begin
  if v_caller is null then
    perform vault_enclave.append_audit(null, 'token_store', 'denied', 'no_caller', null); return null;
  end if;
  if p_token_type is null or p_token_type not in ('vtk', 'vcc', 'mpc', 'sdm') then
    perform vault_enclave.append_audit(v_caller, 'token_store', 'denied', 'bad_type', null); return null;
  end if;
  if p_encrypted_payload is null or octet_length(p_encrypted_payload) not between 1600 and 65536
     or substring(p_encrypted_payload from 1 for 4) <> '\x52564531'::bytea then
    perform vault_enclave.append_audit(v_caller, 'token_store', 'denied', 'not_an_envelope', null); return null;
  end if;
  if not exists (select 1 from public.users u where u.id = v_caller) then
    perform vault_enclave.append_audit(v_caller, 'token_store', 'denied', 'unknown_member', null); return null;
  end if;
  -- 256 random bits from the database's CSPRNG; the caller never chooses a ref.
  v_ref := p_token_type || '_' || pg_catalog.encode(public.gen_random_bytes(32), 'hex');
  insert into vault_enclave.opaque_tokens (token_ref, token_type, owner_user_id, encrypted_payload)
  values (v_ref, p_token_type, v_caller, p_encrypted_payload);
  perform vault_enclave.append_audit(v_caller, 'token_store', 'granted', 'ok', v_ref);
  return v_ref;
end $function$

CREATE OR REPLACE FUNCTION vault_enclave.verify_audit_chain()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  r record;
  v_prev bytea := pg_catalog.decode(pg_catalog.repeat('00', 32), 'hex');
begin
  for r in select * from vault_enclave.audit_logs order by seq loop
    if r.prev_hash <> v_prev or r.entry_hash <> vault_enclave.audit_entry_hash(
         r.prev_hash, r.occurred_at, r.actor_user_id, r.action, r.outcome, r.reason, r.token_ref) then
      return false;
    end if;
    v_prev := r.entry_hash;
  end loop;
  return true;
end $function$
